REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('2744', '14', 'specs', 'Panduan Memilih Harga Grosir Roster Beton Khusus Rekanan Kontraktor', '<div class=\'grid grid-cols-1 md:grid-cols-3 gap-6\'><div class=\'p-6 rounded-2xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700\'><div class=\'text-2xl mb-2\'>📏</div><h4 class=\'font-bold text-slate-900 dark:text-white text-sm mb-2\'>1. Ukuran & Kebutuhan Dinding</h4><p class=\'text-xs text-slate-600 dark:text-slate-300 leading-relaxed\'>Ukuran modular 20×20 cm (isi 25 keping/m²). Rumus hitung: Luas Dinding (m²) × 25 pcs + 3–5% margin aman cadangan tukang.</p></div><div class=\'p-6 rounded-2xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700\'><div class=\'text-2xl mb-2\'>🧱</div><h4 class=\'font-bold text-slate-900 dark:text-white text-sm mb-2\'>2. Ketebalan 10cm vs 8cm</h4><p class=\'text-xs text-slate-600 dark:text-slate-300 leading-relaxed\'>Tebal 10 cm sangat kokoh untuk dinding pagar luar & fasad lantai 1. Tebal 8 cm lebih ringan untuk partisi ruangan & fasad atas.</p></div><div class=\'p-6 rounded-2xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700\'><div class=\'text-2xl mb-2\'>✨</div><h4 class=\'font-bold text-slate-900 dark:text-white text-sm mb-2\'>3. Pilihan Warna & Finishing</h4><p class=\'text-xs text-slate-600 dark:text-slate-300 leading-relaxed\'>Tersedia warna Abu Natural dan Semen Putih. Permukaan keping padat dan halus, siap diekspos natural atau dicat warna sesuai konsep.</p></div></div>', '3', '1', NULL, NULL, '2026-08-30T23:57:23.000000Z', '2026-08-30T23:57:23.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('2745', '14', 'faq', 'Pertanyaan Umum Seputar Harga Grosir Roster Beton Khusus Rekanan Kontraktor', '<div class=\'space-y-4\'><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Berapa minimum pemesanan (MOQ) di IndoRoster?</strong><br>IndoRoster memberlakukan MOQ terverifikasi: Minimum 1.000 pcs untuk retail/pembelian awal dan 5.000 pcs untuk pengadaan proyek/grosir (berlaku merata untuk seluruh motif tanpa kecuali).</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Berapa keping roster yang dibutuhkan untuk 1 meter persegi dinding?</strong><br>Untuk ukuran standar 20×20 cm, dibutuhkan tepat 25 keping per 1 m² luas dinding. Kami sarankan menambah 3–5% sebagai margin aman cadangan potongan tukang.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Apakah ada garansi jika terdapat keping roster yang pecah di perjalanan?</strong><br>Ya, IndoRoster memberikan garansi penggantian keping baru 100% tanpa biaya tambahan jika ditemukan material yang rusak atau pecah saat pengiriman armada kami tiba di lokasi.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Apakah IndoRoster melayani pengiriman bertahap (batch delivery) untuk proyek perumahan?</strong><br>Sangat bisa. Untuk proyek cluster perumahan atau gedung komersial, kami dapat mengatur jadwal pengiriman berkala (misal 1.000–2.000 pcs per pengiriman) mengikuti kecepatan pemasangan tukang di lapangan.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Bagaimana cara berkonsultasi dan mendapatkan penawaran harga resmi?</strong><br>Anda dapat langsung menghubungi tim penjualan kami melalui WhatsApp dengan menginformasikan motif yang dipilih, estimasi kebutuhan keping, serta alamat tujuan pengiriman.</div></div>', '4', '1', NULL, NULL, '2026-08-30T23:57:23.000000Z', '2026-08-30T23:57:23.000000Z');
REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('17', 'supplier-roster-untuk-developer', 'project', 'supplier roster untuk developer', '[\"supplier roster untuk developer murah\",\"harga supplier roster untuk developer\",\"katalog supplier roster untuk developer\"]', 'bofu', 'developer', 'perumahan', NULL, NULL, NULL, 'Supplier Roster Beton Rekanan Developer Perumahan - IndoRoster', 'Pengadaan supplier roster untuk developer skala puluhan hingga ratusan unit. Motif seragam, cetak padat kokoh, pengiriman bertahap langsung pabrik Plered.', NULL, NULL, NULL, NULL, '', 'Supplier Roster Beton Rekanan Developer Perumahan', 'Membangun kawasan perumahan 50 hingga 100 unit memerlukan keseragaman visual fasad dan kepastian pasokan material jangka panjang. IndoRoster menjamin konsistensi motif dan dimensi keping roster untuk seluruh unit rumah di cluster Anda.', 'Jaminan keseragaman motif antar batch produksi untuk menjaga estetika visual cluster perumahan yang seragam dan elegan.', 'Kapasitas pabrik 10.000 pcs/bulan, MOQ grosir proyek 5.000 pcs, kontrak suplai bertahap.', NULL, 'whatsapp', 'Diskusikan Pengadaan Cluster (WhatsApp)', NULL, 'featured', NULL, NULL, NULL, NULL, '0', '80', '{\"search_intent_match\":5,\"buyer_relevance\":5,\"product_relevance\":5,\"unique_information\":3,\"evidence\":5,\"local_relevance\":3,\"commercial_value\":5,\"conversion_clarity\":3,\"ux_readability\":5,\"internal_linking\":0,\"originality\":3,\"factual_accuracy\":5}', 'published', '2026-08-01T23:57:24.000000Z', '2026-08-30T23:57:24.000000Z', NULL, '2026-08-30T21:11:47.000000Z', '2026-08-31T15:01:28.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('2754', '17', 'problem', 'Menjaga Konsistensi Estetika Fasad untuk Puluhan Unit Cluster', '<p>Saat mengembangkan kawasan perumahan 50 hingga 100 unit, menjaga keseragaman tampak depan (fasad) adalah kunci utama daya tarik pembeli properti. Keterlambatan pasokan material atau ketidaksamaan motif antar tahap pembangunan dapat merusak estetika keseluruhan cluster.</p><p>Developer membutuhkan mitra produsen roster terpercaya yang memiliki kapasitas produksi stabil 10.000 pcs per bulan, jaminan mutu cetak padat yang konsisten, dan fleksibilitas pengiriman bertahap (batch delivery) langsung ke lokasi proyek perumahan.</p>', '1', '1', NULL, NULL, '2026-08-30T23:57:24.000000Z', '2026-08-30T23:57:24.000000Z');
