REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('2857', '42', 'faq', 'Pertanyaan Umum Seputar Elemen Roster Beton dalam Desain Arsitektur Tropis Modern', '<div class=\'space-y-4\'><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Berapa minimum pemesanan (MOQ) di IndoRoster?</strong><br>IndoRoster memberlakukan MOQ terverifikasi: Minimum 1.000 pcs untuk retail/pembelian awal dan 5.000 pcs untuk pengadaan proyek/grosir (berlaku merata untuk seluruh motif tanpa kecuali).</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Berapa keping roster yang dibutuhkan untuk 1 meter persegi dinding?</strong><br>Untuk ukuran standar 20×20 cm, dibutuhkan tepat 25 keping per 1 m² luas dinding. Kami sarankan menambah 3–5% sebagai margin aman cadangan potongan tukang.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Apakah ada garansi jika terdapat keping roster yang pecah di perjalanan?</strong><br>Ya, IndoRoster memberikan garansi penggantian keping baru 100% tanpa biaya tambahan jika ditemukan material yang rusak atau pecah saat pengiriman armada kami tiba di lokasi.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Apakah keping roster bisa langsung diekspos atau dicat?</strong><br>Bisa. Permukaan roster IndoRoster padat dan halus, sehingga dapat langsung diekspos dengan cairan pelapis coating bening atau dicat warna sesuai selera arsitektur Anda.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Bagaimana cara berkonsultasi dan mendapatkan penawaran harga resmi?</strong><br>Anda dapat langsung menghubungi tim penjualan kami melalui WhatsApp dengan menginformasikan motif yang dipilih, estimasi kebutuhan keping, serta alamat tujuan pengiriman.</div></div>', '4', '1', NULL, NULL, '2026-08-30T23:57:33.000000Z', '2026-08-30T23:57:33.000000Z');
REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('43', 'roster-dinding-depan-rumah', 'usecase', 'roster dinding depan rumah', '[\"motif roster dinding depan rumah\",\"harga roster dinding depan rumah\",\"katalog roster dinding depan rumah\"]', 'mofu', 'arsitek', 'fasad', NULL, NULL, NULL, 'Aksen Roster Beton Cantik untuk Dinding Depan Rumah - IndoRoster', 'Koleksi roster dinding depan rumah aneka motif geometris dan floral. Tahan cuaca tropis, mereduksi panas, dan menciptakan bayangan dinamis yang estetis.', NULL, NULL, NULL, NULL, '', 'Aksen Roster Beton Cantik untuk Dinding Depan Rumah', 'Fasad adalah wajah utama sebuah bangunan. Penggunaan roster beton sebagai elemen dinding tampak depan tidak hanya memberikan privasi dan sirkulasi angin, namun juga menghadirkan permainan bayangan cahaya matahari yang artistik di dalam ruangan.', 'Kombinasi 45+ motif yang dapat dipadukan secara modular untuk menciptakan pola fasad arsitektural yang unik.', 'Material adukan padat cetak padat kokoh tahan rembes air dan terpaan hujan angin tropis.', NULL, 'whatsapp', 'Lihat Katalog Fasad (WhatsApp)', NULL, 'all', NULL, NULL, NULL, NULL, '0', '76', '{\"search_intent_match\":5,\"buyer_relevance\":4,\"product_relevance\":5,\"unique_information\":3,\"evidence\":5,\"local_relevance\":3,\"commercial_value\":4,\"conversion_clarity\":3,\"ux_readability\":5,\"internal_linking\":0,\"originality\":3,\"factual_accuracy\":5}', 'published', '2026-08-03T23:57:34.000000Z', '2026-08-30T23:57:34.000000Z', NULL, '2026-08-30T21:11:48.000000Z', '2026-08-31T15:01:48.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('2858', '43', 'problem', 'Harmoni Fasad Tropis Modern: Pencahayaan Alami, Privasi, dan Bayangan Estetis', '<p>Merancang fasad eksterior pada bangunan tropis modern memerlukan perpaduan antara perlindungan cuaca dan nilai seni arsitektur. Dinding masif kerap membuat hunian terasa kaku dan minim ventilasi alami.</p><p>Roster arsitektural berfungsi sebagai secondary skin yang efektif mereduksi silau matahari (solar shading) sekaligus menciptakan permainan bayangan cahaya yang dinamis di dalam ruangan. Bukaan lubang geometrisnya mengalirkan sirkulasi udara bebas sekaligus menjadi elemen signature visual yang mempercantik tampilan bangunan.</p>', '1', '1', NULL, NULL, '2026-08-30T23:57:36.000000Z', '2026-08-30T23:57:36.000000Z');
