REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('56', 'vendor-roster-beton-untuk-proyek', 'pillar', 'vendor roster beton untuk proyek', '[\"rfq vendor roster beton untuk proyek\",\"tender vendor roster beton untuk proyek\",\"legalitas vendor roster beton untuk proyek\"]', 'bofu', 'procurement', 'komersial', NULL, NULL, NULL, 'Vendor Resmi Pengadaan Roster Beton untuk Proyek Konstruksi - IndoRoster', 'Layanan vendor roster beton untuk proyek. Penerbitan faktur pajak resmi, legalitas NIB & NPWP lengkap, surat jalan dan BAST untuk pelaporan pengadaan.', NULL, NULL, NULL, NULL, '', 'Vendor Resmi Pengadaan Roster Beton untuk Proyek Konstruksi', 'Divisi procurement korporasi dan tim purchasing proyek BUMN/swasta membutuhkan vendor material yang memiliki kepatuhan administratif lengkap. IndoRoster menerbitkan seluruh dokumen resmi pengadaan yang dibutuhkan untuk audit dan penagihan termin proyek Anda.', 'Integritas dokumen pengadaan: Faktur Pajak PPN e-Faktur resmi, Surat Jalan bermaterai, dan Berita Acara Serah Terima (BAST).', 'Legalitas badan usaha lengkap (NIB, NPWP, SIUP) dengan rekening bank atas nama perusahaan resmi.', NULL, 'whatsapp', 'Kirim Permintaan Quotation (RFQ)', NULL, 'featured', NULL, NULL, NULL, NULL, '0', '80', '{\"search_intent_match\":5,\"buyer_relevance\":5,\"product_relevance\":5,\"unique_information\":3,\"evidence\":5,\"local_relevance\":3,\"commercial_value\":5,\"conversion_clarity\":3,\"ux_readability\":5,\"internal_linking\":0,\"originality\":3,\"factual_accuracy\":5}', 'published', '2026-08-11T23:57:53.000000Z', '2026-08-30T23:57:53.000000Z', NULL, '2026-08-30T21:11:48.000000Z', '2026-08-30T23:57:53.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('2910', '56', 'problem', 'Kebutuhan Vendor Manufaktur Terpercaya untuk Kelancaran Pengadaan', '<p>Divisi pengadaan korporat dan panitia pengadaan proyek membutuhkan partner suplai material yang memiliki integritas produksi dan kepastian legalitas usaha.</p><p>Ketiadaan Surat Penawaran Harga (SPH) resmi atau ketidakjelasan kapasitas pengiriman vendor dapat menghambat pelaporan administrasi dan jadwal serah terima proyek. IndoRoster memberikan kepastian suplai tangan pertama dengan dokumen penawaran transparan dan jadwal kirim terencana.</p>', '1', '1', NULL, NULL, '2026-08-30T23:57:54.000000Z', '2026-08-30T23:57:54.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('2911', '56', 'solution', 'Solusi Roster Minimalis IndoRoster: Presisi, Padat & 45+ Pilihan Motif', '<p>IndoRoster memproduksi aneka ragam roster minimalis arsitektural langsung dari sentra pengrajin Plered Purwakarta dengan standar kerapian tinggi. Kami mengelompokkan koleksi motif kami sesuai kebutuhan fungsional bangunan Anda:</p><ul><li><strong>Roster Anti-Tampias Hujan (Motif Nako LS & Nako Sipit):</strong> Dirancang dengan kemiringan sirip khusus yang efektif menghalau percikan air hujan agar tidak masuk ke dalam ruangan, sangat ideal untuk area balkon, ruang cuci jemur, dan dinding samping terbuka.</li><li><strong>Roster Karakter 3D & Signature (Motif Petir, MMC, Arrow, Batman):</strong> Memiliki permukaan timbul berdimensi yang memberikan tekstur tegas pada dinding fasad depan ruko, kafe, maupun rumah tinggal modern.</li><li><strong>Roster Minimalis Geometris (Motif JaboL, PCL, Kotak):</strong> Mengusung garis tegas sederhana yang selaras dengan arsitektur perumahan modern, menciptakan tampilan dinding yang bersih, rapi, dan simetris.</li><li><strong>Cetak Padat Rapi oleh Pengrajin:</strong> Setiap keping dicetak padat oleh tangan terampil pengrajin dengan sudut siku 90 derajat yang mempermudah tukang memasang dinding secara lurus dan presisi.</li></ul>', '2', '1', NULL, NULL, '2026-08-30T23:57:54.000000Z', '2026-08-30T23:57:54.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('2912', '56', 'specs', 'Panduan Memilih Vendor Resmi Pengadaan Roster Beton untuk Proyek Konstruksi', '<div class=\'grid grid-cols-1 md:grid-cols-3 gap-6\'><div class=\'p-6 rounded-2xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700\'><div class=\'text-2xl mb-2\'>📏</div><h4 class=\'font-bold text-slate-900 dark:text-white text-sm mb-2\'>1. Ukuran & Kebutuhan Dinding</h4><p class=\'text-xs text-slate-600 dark:text-slate-300 leading-relaxed\'>Ukuran modular 20×20 cm (isi 25 keping/m²). Rumus hitung: Luas Dinding (m²) × 25 pcs + 3–5% margin aman cadangan tukang.</p></div><div class=\'p-6 rounded-2xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700\'><div class=\'text-2xl mb-2\'>🧱</div><h4 class=\'font-bold text-slate-900 dark:text-white text-sm mb-2\'>2. Ketebalan 10cm vs 8cm</h4><p class=\'text-xs text-slate-600 dark:text-slate-300 leading-relaxed\'>Tebal 10 cm sangat kokoh untuk dinding pagar luar & fasad lantai 1. Tebal 8 cm lebih ringan untuk partisi ruangan & fasad atas.</p></div><div class=\'p-6 rounded-2xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700\'><div class=\'text-2xl mb-2\'>✨</div><h4 class=\'font-bold text-slate-900 dark:text-white text-sm mb-2\'>3. Pilihan Warna & Finishing</h4><p class=\'text-xs text-slate-600 dark:text-slate-300 leading-relaxed\'>Tersedia warna Abu Natural dan Semen Putih. Permukaan keping padat dan halus, siap diekspos natural atau dicat warna sesuai konsep.</p></div></div>', '3', '1', NULL, NULL, '2026-08-30T23:57:54.000000Z', '2026-08-30T23:57:54.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('2913', '56', 'faq', 'Pertanyaan Umum Seputar Vendor Resmi Pengadaan Roster Beton untuk Proyek Konstruksi', '<div class=\'space-y-4\'><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Berapa minimum pemesanan (MOQ) di IndoRoster?</strong><br>IndoRoster memberlakukan MOQ terverifikasi: Minimum 1.000 pcs untuk retail/pembelian awal dan 5.000 pcs untuk pengadaan proyek/grosir (berlaku merata untuk seluruh motif tanpa kecuali).</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Berapa keping roster yang dibutuhkan untuk 1 meter persegi dinding?</strong><br>Untuk ukuran standar 20×20 cm, dibutuhkan tepat 25 keping per 1 m² luas dinding. Kami sarankan menambah 3–5% sebagai margin aman cadangan potongan tukang.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Apakah ada garansi jika terdapat keping roster yang pecah di perjalanan?</strong><br>Ya, IndoRoster memberikan garansi penggantian keping baru 100% tanpa biaya tambahan jika ditemukan material yang rusak atau pecah saat pengiriman armada kami tiba di lokasi.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Apakah keping roster bisa langsung diekspos atau dicat?</strong><br>Bisa. Permukaan roster IndoRoster padat dan halus, sehingga dapat langsung diekspos dengan cairan pelapis coating bening atau dicat warna sesuai selera arsitektur Anda.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Bagaimana cara berkonsultasi dan mendapatkan penawaran harga resmi?</strong><br>Anda dapat langsung menghubungi tim penjualan kami melalui WhatsApp dengan menginformasikan motif yang dipilih, estimasi kebutuhan keping, serta alamat tujuan pengiriman.</div></div>', '4', '1', NULL, NULL, '2026-08-30T23:57:54.000000Z', '2026-08-30T23:57:54.000000Z');
REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('57', 'pengadaan-roster-beton', 'pillar', 'pengadaan roster beton', '[\"rfq pengadaan roster beton\",\"tender pengadaan roster beton\",\"legalitas pengadaan roster beton\"]', 'bofu', 'procurement', 'komersial', NULL, NULL, NULL, 'Layanan Pengadaan Material Roster Beton Bersertifikasi - IndoRoster', 'Layanan pengadaan roster beton. Penerbitan faktur pajak resmi, legalitas NIB & NPWP lengkap, surat jalan dan BAST untuk pelaporan pengadaan.', NULL, NULL, NULL, NULL, '', 'Layanan Pengadaan Material Roster Beton Bersertifikasi', 'Divisi procurement korporasi dan tim purchasing proyek BUMN/swasta membutuhkan vendor material yang memiliki kepatuhan administratif lengkap. IndoRoster menerbitkan seluruh dokumen resmi pengadaan yang dibutuhkan untuk audit dan penagihan termin proyek Anda.', 'Integritas dokumen pengadaan: Faktur Pajak PPN e-Faktur resmi, Surat Jalan bermaterai, dan Berita Acara Serah Terima (BAST).', 'Legalitas badan usaha lengkap (NIB, NPWP, SIUP) dengan rekening bank atas nama perusahaan resmi.', NULL, 'whatsapp', 'Kirim Permintaan Quotation (RFQ)', NULL, 'featured', NULL, NULL, NULL, NULL, '0', '80', '{\"search_intent_match\":5,\"buyer_relevance\":5,\"product_relevance\":5,\"unique_information\":3,\"evidence\":5,\"local_relevance\":3,\"commercial_value\":5,\"conversion_clarity\":3,\"ux_readability\":5,\"internal_linking\":0,\"originality\":3,\"factual_accuracy\":5}', 'published', '2026-08-06T23:57:54.000000Z', '2026-08-30T23:57:54.000000Z', NULL, '2026-08-30T21:11:48.000000Z', '2026-08-30T23:57:54.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('2914', '57', 'problem', 'Kebutuhan Vendor Manufaktur Terpercaya untuk Kelancaran Pengadaan', '<p>Divisi pengadaan korporat dan panitia pengadaan proyek membutuhkan partner suplai material yang memiliki integritas produksi dan kepastian legalitas usaha.</p><p>Ketiadaan Surat Penawaran Harga (SPH) resmi atau ketidakjelasan kapasitas pengiriman vendor dapat menghambat pelaporan administrasi dan jadwal serah terima proyek. IndoRoster memberikan kepastian suplai tangan pertama dengan dokumen penawaran transparan dan jadwal kirim terencana.</p>', '1', '1', NULL, NULL, '2026-08-30T23:57:55.000000Z', '2026-08-30T23:57:55.000000Z');
