REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('2920', '58', 'specs', 'Panduan Memilih Permintaan Surat Penawaran Harga (Quotation) Roster Beton', '<div class=\'grid grid-cols-1 md:grid-cols-3 gap-6\'><div class=\'p-6 rounded-2xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700\'><div class=\'text-2xl mb-2\'>📏</div><h4 class=\'font-bold text-slate-900 dark:text-white text-sm mb-2\'>1. Ukuran & Kebutuhan Dinding</h4><p class=\'text-xs text-slate-600 dark:text-slate-300 leading-relaxed\'>Ukuran modular 20×20 cm (isi 25 keping/m²). Rumus hitung: Luas Dinding (m²) × 25 pcs + 3–5% margin aman cadangan tukang.</p></div><div class=\'p-6 rounded-2xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700\'><div class=\'text-2xl mb-2\'>🧱</div><h4 class=\'font-bold text-slate-900 dark:text-white text-sm mb-2\'>2. Ketebalan 10cm vs 8cm</h4><p class=\'text-xs text-slate-600 dark:text-slate-300 leading-relaxed\'>Tebal 10 cm sangat kokoh untuk dinding pagar luar & fasad lantai 1. Tebal 8 cm lebih ringan untuk partisi ruangan & fasad atas.</p></div><div class=\'p-6 rounded-2xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700\'><div class=\'text-2xl mb-2\'>✨</div><h4 class=\'font-bold text-slate-900 dark:text-white text-sm mb-2\'>3. Pilihan Warna & Finishing</h4><p class=\'text-xs text-slate-600 dark:text-slate-300 leading-relaxed\'>Tersedia warna Abu Natural dan Semen Putih. Permukaan keping padat dan halus, siap diekspos natural atau dicat warna sesuai konsep.</p></div></div>', '3', '1', NULL, NULL, '2026-08-30T23:57:58.000000Z', '2026-08-30T23:57:58.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('2921', '58', 'faq', 'Pertanyaan Umum Seputar Permintaan Surat Penawaran Harga (Quotation) Roster Beton', '<div class=\'space-y-4\'><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Berapa minimum pemesanan (MOQ) di IndoRoster?</strong><br>IndoRoster memberlakukan MOQ terverifikasi: Minimum 1.000 pcs untuk retail/pembelian awal dan 5.000 pcs untuk pengadaan proyek/grosir (berlaku merata untuk seluruh motif tanpa kecuali).</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Berapa keping roster yang dibutuhkan untuk 1 meter persegi dinding?</strong><br>Untuk ukuran standar 20×20 cm, dibutuhkan tepat 25 keping per 1 m² luas dinding. Kami sarankan menambah 3–5% sebagai margin aman cadangan potongan tukang.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Apakah ada garansi jika terdapat keping roster yang pecah di perjalanan?</strong><br>Ya, IndoRoster memberikan garansi penggantian keping baru 100% tanpa biaya tambahan jika ditemukan material yang rusak atau pecah saat pengiriman armada kami tiba di lokasi.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Apakah keping roster bisa langsung diekspos atau dicat?</strong><br>Bisa. Permukaan roster IndoRoster padat dan halus, sehingga dapat langsung diekspos dengan cairan pelapis coating bening atau dicat warna sesuai selera arsitektur Anda.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Bagaimana cara berkonsultasi dan mendapatkan penawaran harga resmi?</strong><br>Anda dapat langsung menghubungi tim penjualan kami melalui WhatsApp dengan menginformasikan motif yang dipilih, estimasi kebutuhan keping, serta alamat tujuan pengiriman.</div></div>', '4', '1', NULL, NULL, '2026-08-30T23:57:58.000000Z', '2026-08-30T23:57:58.000000Z');
REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('59', 'penawaran-roster-beton-untuk-proyek', 'pillar', 'penawaran roster beton untuk proyek', '[\"rfq penawaran roster beton untuk proyek\",\"tender penawaran roster beton untuk proyek\",\"legalitas penawaran roster beton untuk proyek\"]', 'bofu', 'procurement', 'komersial', NULL, NULL, NULL, 'Pengajuan Penawaran Harga Resmi Roster untuk Tender Proyek - IndoRoster', 'Layanan penawaran roster beton untuk proyek. Penerbitan faktur pajak resmi, legalitas NIB & NPWP lengkap, surat jalan dan BAST untuk pelaporan pengadaan.', NULL, NULL, NULL, NULL, '', 'Pengajuan Penawaran Harga Resmi Roster untuk Tender Proyek', 'Divisi procurement korporasi dan tim purchasing proyek BUMN/swasta membutuhkan vendor material yang memiliki kepatuhan administratif lengkap. IndoRoster menerbitkan seluruh dokumen resmi pengadaan yang dibutuhkan untuk audit dan penagihan termin proyek Anda.', 'Integritas dokumen pengadaan: Faktur Pajak PPN e-Faktur resmi, Surat Jalan bermaterai, dan Berita Acara Serah Terima (BAST).', 'Legalitas badan usaha lengkap (NIB, NPWP, SIUP) dengan rekening bank atas nama perusahaan resmi.', NULL, 'whatsapp', 'Kirim Permintaan Quotation (RFQ)', NULL, 'featured', NULL, NULL, NULL, NULL, '0', '80', '{\"search_intent_match\":5,\"buyer_relevance\":5,\"product_relevance\":5,\"unique_information\":3,\"evidence\":5,\"local_relevance\":3,\"commercial_value\":5,\"conversion_clarity\":3,\"ux_readability\":5,\"internal_linking\":0,\"originality\":3,\"factual_accuracy\":5}', 'published', '2026-08-17T23:57:58.000000Z', '2026-08-30T23:57:58.000000Z', NULL, '2026-08-30T21:11:48.000000Z', '2026-08-30T23:57:58.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('2922', '59', 'problem', 'Kebutuhan Vendor Manufaktur Terpercaya untuk Kelancaran Pengadaan', '<p>Divisi pengadaan korporat dan panitia pengadaan proyek membutuhkan partner suplai material yang memiliki integritas produksi dan kepastian legalitas usaha.</p><p>Ketiadaan Surat Penawaran Harga (SPH) resmi atau ketidakjelasan kapasitas pengiriman vendor dapat menghambat pelaporan administrasi dan jadwal serah terima proyek. IndoRoster memberikan kepastian suplai tangan pertama dengan dokumen penawaran transparan dan jadwal kirim terencana.</p>', '1', '1', NULL, NULL, '2026-08-30T23:57:59.000000Z', '2026-08-30T23:57:59.000000Z');
