REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('2977', '72', 'faq', 'Pertanyaan Umum Seputar Roster Beton Ukuran Standar 20x20 cm (Isi 25 pcs/m2)', '<div class=\'space-y-4\'><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Berapa minimum pemesanan (MOQ) di IndoRoster?</strong><br>IndoRoster memberlakukan MOQ terverifikasi: Minimum 1.000 pcs untuk retail/pembelian awal dan 5.000 pcs untuk pengadaan proyek/grosir (berlaku merata untuk seluruh motif tanpa kecuali).</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Berapa keping roster yang dibutuhkan untuk 1 meter persegi dinding?</strong><br>Untuk ukuran standar 20×20 cm, dibutuhkan tepat 25 keping per 1 m² luas dinding. Kami sarankan menambah 3–5% sebagai margin aman cadangan potongan tukang.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Apakah ada garansi jika terdapat keping roster yang pecah di perjalanan?</strong><br>Ya, IndoRoster memberikan garansi penggantian keping baru 100% tanpa biaya tambahan jika ditemukan material yang rusak atau pecah saat pengiriman armada kami tiba di lokasi.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Apakah keping roster bisa langsung diekspos atau dicat?</strong><br>Bisa. Permukaan roster IndoRoster padat dan halus, sehingga dapat langsung diekspos dengan cairan pelapis coating bening atau dicat warna sesuai selera arsitektur Anda.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Bagaimana cara berkonsultasi dan mendapatkan penawaran harga resmi?</strong><br>Anda dapat langsung menghubungi tim penjualan kami melalui WhatsApp dengan menginformasikan motif yang dipilih, estimasi kebutuhan keping, serta alamat tujuan pengiriman.</div></div>', '4', '1', NULL, NULL, '2026-08-30T23:58:18.000000Z', '2026-08-30T23:58:18.000000Z');
REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('73', 'roster-beton-tebal-8cm', 'product_landing', 'roster beton tebal 8cm', '[\"katalog roster beton tebal 8cm\",\"harga roster beton tebal 8cm\",\"beli roster beton tebal 8cm\"]', 'mofu', 'umum', 'umum', NULL, NULL, NULL, 'Roster Beton Tebal 8 cm Ringan untuk Partisi & Fasad Atas - IndoRoster', 'Katalog roster beton tebal 8cm pabrik Plered. Cetak padat cetak tumbuk padat, siku presisi 90 derajat, permukaan halus siap finishing cat atau expose.', NULL, NULL, NULL, NULL, '', 'Roster Beton Tebal 8 cm Ringan untuk Partisi & Fasad Atas', 'Eksplorasi ragam pilihan motif roster beton kualitas prima dari IndoRoster. Dibuat dengan cetakan baja presisi tinggi, menghasilkan tepian sudut yang rapi, padat, dan bebas retak rambut untuk kesempurnaan detail arsitektur Anda.', 'Presisi ukuran dimensi terstandarisasi untuk pemasangan modular yang simetris dan rapi.', 'Material beton cetak padat kokoh, berat seimbang 3.8–4.2 kg per keping ukuran 20x20x10 cm.', NULL, 'whatsapp', 'Pesan Motif Ini via WhatsApp', NULL, 'all', NULL, NULL, NULL, NULL, '0', '74', '{\"search_intent_match\":5,\"buyer_relevance\":4,\"product_relevance\":5,\"unique_information\":2,\"evidence\":5,\"local_relevance\":3,\"commercial_value\":4,\"conversion_clarity\":3,\"ux_readability\":5,\"internal_linking\":0,\"originality\":3,\"factual_accuracy\":5}', 'published', '2026-08-07T23:58:18.000000Z', '2026-08-30T23:58:18.000000Z', NULL, '2026-08-30T21:11:49.000000Z', '2026-08-31T15:01:51.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('2978', '73', 'problem', 'Mengapa Memilih Roster Minimalis Kualitas Cetak Padat Pengrajin?', '<p>Banyak produk loster di pasaran dibuat dengan adukan pasir kasar yang mudah rontok atau gompal saat dipasang. Membeli <strong>roster beton tebal 8cm</strong> langsung dari sentra pabrikasi pengrajin Plered menjamin keping roster yang dicetak padat, permukaannya halus, dan memiliki sudut siku presisi untuk keindahan jangka panjang rumah Anda.</p>', '1', '1', NULL, NULL, '2026-08-30T23:58:19.000000Z', '2026-08-30T23:58:19.000000Z');
