REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3000', '78', 'specs', 'Panduan Memilih Supplier Roster Beton untuk Proyek di Bogor', '<div class=\'grid grid-cols-1 md:grid-cols-3 gap-6\'><div class=\'p-6 rounded-2xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700\'><div class=\'text-2xl mb-2\'>📏</div><h4 class=\'font-bold text-slate-900 dark:text-white text-sm mb-2\'>1. Dimensi Modular</h4><p class=\'text-xs text-slate-600 dark:text-slate-300 leading-relaxed\'>Ukuran standar 20×20×10 cm dan 20×20×8 cm. Untuk luasan 1 m² dinding dibutuhkan tepat 25 keping roster.</p></div><div class=\'p-6 rounded-2xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700\'><div class=\'text-2xl mb-2\'>🎨</div><h4 class=\'font-bold text-slate-900 dark:text-white text-sm mb-2\'>2. Pilihan Warna Natural</h4><p class=\'text-xs text-slate-600 dark:text-slate-300 leading-relaxed\'>Tersedia varian Abu Semen Natural untuk konsep industrial dan varian Semen Putih untuk tampilan bersih elegan.</p></div><div class=\'p-6 rounded-2xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700\'><div class=\'text-2xl mb-2\'>🚚</div><h4 class=\'font-bold text-slate-900 dark:text-white text-sm mb-2\'>3. Pengiriman Bogor</h4><p class=\'text-xs text-slate-600 dark:text-slate-300 leading-relaxed\'>Armada truk pabrik langsung mengantarkan pesanan ke lokasi proyek di Bogor dengan garansi bebas pecah 100%.</p></div></div>', '3', '1', NULL, NULL, '2026-08-30T23:58:26.000000Z', '2026-08-30T23:58:26.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3001', '78', 'faq', 'Pertanyaan Umum Seputar Supplier Roster Beton untuk Proyek di Bogor', '<div class=\'space-y-4\'><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Bagaimana sistem pengiriman pesanan roster ke wilayah Bogor?</strong><br>Pengiriman ke Bogor dikirimkan langsung dari sentra pabrik IndoRoster di Plered Purwakarta menggunakan armada truk terdedikasi yang disusun rapi di atas palet kayu aman.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Berapa lama estimasi pengiriman sampai ke lokasi proyek di Bogor?</strong><br>Setelah pesanan dikonfirmasi dan jadwal muat disepakati, pengiriman ke area Bogor biasanya membutuhkan waktu 1–2 hari kerja tergantung jarak tempuh dan akses masuk jalan proyek.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Apakah ada garansi jika terdapat keping roster yang pecah di perjalanan?</strong><br>Ya, IndoRoster memberikan garansi penggantian keping baru 100% tanpa biaya tambahan jika ditemukan material yang rusak atau pecah saat pengiriman armada kami tiba di lokasi.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Apakah IndoRoster melayani pengiriman bertahap (batch delivery) untuk proyek perumahan?</strong><br>Sangat bisa. Untuk proyek cluster perumahan atau gedung komersial, kami dapat mengatur jadwal pengiriman berkala (misal 1.000–2.000 pcs per pengiriman) mengikuti kecepatan pemasangan tukang di lapangan.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Bagaimana cara berkonsultasi dan mendapatkan penawaran harga resmi?</strong><br>Anda dapat langsung menghubungi tim penjualan kami melalui WhatsApp dengan menginformasikan motif yang dipilih, estimasi kebutuhan keping, serta alamat tujuan pengiriman.</div></div>', '4', '1', NULL, NULL, '2026-08-30T23:58:26.000000Z', '2026-08-30T23:58:26.000000Z');
REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('79', 'supplier-roster-beton-depok', 'location', 'supplier roster beton depok', '[\"jual roster beton Depok\",\"pabrik roster Depok\",\"harga roster Depok\"]', 'bofu', 'kontraktor', 'umum', NULL, NULL, 'Depok', 'Supplier Roster Beton di Depok - Kirim Langsung Pabrik IndoRoster', 'Supplier roster beton terpercaya untuk wilayah Depok. Pengiriman material roster hunian modern dan ruko area Sawangan, Margonda, Cinere, dan Grand Depok City. Garansi bebas pecah, kapasitas 10.000 pcs/bln.', NULL, NULL, NULL, NULL, '', 'Supplier Roster Beton untuk Proyek di Depok', 'Sedang mengerjakan proyek konstruksi, renovasi gedung, atau pembangunan cluster perumahan di Depok? IndoRoster menyediakan solusi suplai aneka motif roster beton presisi langsung dari sentra pabrik Plered Purwakarta dengan armada pengiriman terencana.', 'Akses pengiriman armada truk langsung dari pabrik Purwakarta ke Depok dengan jaminan penggantian keping baru 100% jika terjadi kerusakan selama perjalanan.', 'Pengiriman material roster hunian modern dan ruko area Sawangan, Margonda, Cinere, dan Grand Depok City. Kapasitas pabrik 10.000 pcs/bulan, MOQ retail 1.000 pcs & grosir 5.000 pcs.', NULL, 'whatsapp', 'Konsultasi Pengiriman ke Depok (WhatsApp)', NULL, 'all', NULL, NULL, NULL, NULL, '0', '78', '{\"search_intent_match\":5,\"buyer_relevance\":5,\"product_relevance\":5,\"unique_information\":3,\"evidence\":5,\"local_relevance\":2,\"commercial_value\":5,\"conversion_clarity\":3,\"ux_readability\":5,\"internal_linking\":0,\"originality\":3,\"factual_accuracy\":5}', 'published', '2026-08-20T23:58:27.000000Z', '2026-08-30T23:58:27.000000Z', NULL, '2026-08-30T21:11:49.000000Z', '2026-08-30T23:58:27.000000Z');
