REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3008', '80', 'specs', 'Panduan Memilih Supplier Roster Beton untuk Proyek di Tangerang', '<div class=\'grid grid-cols-1 md:grid-cols-3 gap-6\'><div class=\'p-6 rounded-2xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700\'><div class=\'text-2xl mb-2\'>📏</div><h4 class=\'font-bold text-slate-900 dark:text-white text-sm mb-2\'>1. Dimensi Modular</h4><p class=\'text-xs text-slate-600 dark:text-slate-300 leading-relaxed\'>Ukuran standar 20×20×10 cm dan 20×20×8 cm. Untuk luasan 1 m² dinding dibutuhkan tepat 25 keping roster.</p></div><div class=\'p-6 rounded-2xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700\'><div class=\'text-2xl mb-2\'>🎨</div><h4 class=\'font-bold text-slate-900 dark:text-white text-sm mb-2\'>2. Pilihan Warna Natural</h4><p class=\'text-xs text-slate-600 dark:text-slate-300 leading-relaxed\'>Tersedia varian Abu Semen Natural untuk konsep industrial dan varian Semen Putih untuk tampilan bersih elegan.</p></div><div class=\'p-6 rounded-2xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700\'><div class=\'text-2xl mb-2\'>🚚</div><h4 class=\'font-bold text-slate-900 dark:text-white text-sm mb-2\'>3. Pengiriman Tangerang</h4><p class=\'text-xs text-slate-600 dark:text-slate-300 leading-relaxed\'>Armada truk pabrik langsung mengantarkan pesanan ke lokasi proyek di Tangerang dengan garansi bebas pecah 100%.</p></div></div>', '3', '1', NULL, NULL, '2026-08-30T23:58:28.000000Z', '2026-08-30T23:58:28.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3009', '80', 'faq', 'Pertanyaan Umum Seputar Supplier Roster Beton untuk Proyek di Tangerang', '<div class=\'space-y-4\'><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Bagaimana sistem pengiriman pesanan roster ke wilayah Tangerang?</strong><br>Pengiriman ke Tangerang dikirimkan langsung dari sentra pabrik IndoRoster di Plered Purwakarta menggunakan armada truk terdedikasi yang disusun rapi di atas palet kayu aman.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Berapa lama estimasi pengiriman sampai ke lokasi proyek di Tangerang?</strong><br>Setelah pesanan dikonfirmasi dan jadwal muat disepakati, pengiriman ke area Tangerang biasanya membutuhkan waktu 1–2 hari kerja tergantung jarak tempuh dan akses masuk jalan proyek.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Apakah ada garansi jika terdapat keping roster yang pecah di perjalanan?</strong><br>Ya, IndoRoster memberikan garansi penggantian keping baru 100% tanpa biaya tambahan jika ditemukan material yang rusak atau pecah saat pengiriman armada kami tiba di lokasi.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Apakah IndoRoster melayani pengiriman bertahap (batch delivery) untuk proyek perumahan?</strong><br>Sangat bisa. Untuk proyek cluster perumahan atau gedung komersial, kami dapat mengatur jadwal pengiriman berkala (misal 1.000–2.000 pcs per pengiriman) mengikuti kecepatan pemasangan tukang di lapangan.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Bagaimana cara berkonsultasi dan mendapatkan penawaran harga resmi?</strong><br>Anda dapat langsung menghubungi tim penjualan kami melalui WhatsApp dengan menginformasikan motif yang dipilih, estimasi kebutuhan keping, serta alamat tujuan pengiriman.</div></div>', '4', '1', NULL, NULL, '2026-08-30T23:58:28.000000Z', '2026-08-30T23:58:28.000000Z');
