REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('150', 'roster-beton-tahan-lumut-dan-jamur', 'usecase', 'roster beton anti lumut', '[\"roster beton anti lumut murah\",\"harga roster beton anti lumut\",\"katalog roster beton anti lumut\"]', 'mofu', 'umum', 'umum', NULL, NULL, NULL, 'Roster Beton Padat Anti Lumut & Jamur untuk Daerah Lembab - IndoRoster', 'Solusi roster beton anti lumut tangan pertama pabrik Plered Purwakarta. Presisi tinggi, cetak padat kokoh, kapasitas 10.000 pcs/bln, siap kirim ke lokasi Anda.', NULL, NULL, NULL, NULL, '', 'Roster Beton Padat Anti Lumut & Jamur untuk Daerah Lembab', 'Mengintegrasikan material roster beton pada arsitektur modern membutuhkan ketelitian pemilihan motif dan jaminan mutu cetak padat. IndoRoster memproduksi aneka model loster beton yang dirancang khusus untuk memenuhi standar keindahan visual sekaligus keandalan fungsi bangunan Anda.', 'Pabrikasi presisi sudut 90° dengan mal baja khusus dan mutu beton padat kokoh bergaransi aman sampai lokasi.', 'Kapasitas produksi pabrik 10.000 pcs/bulan, MOQ retail 1.000 pcs, MOQ grosir 5.000 pcs.', NULL, 'whatsapp', 'Konsultasi via WhatsApp', NULL, 'all', NULL, NULL, NULL, NULL, '0', '76', '{\"search_intent_match\":5,\"buyer_relevance\":4,\"product_relevance\":5,\"unique_information\":3,\"evidence\":5,\"local_relevance\":3,\"commercial_value\":4,\"conversion_clarity\":3,\"ux_readability\":5,\"internal_linking\":0,\"originality\":3,\"factual_accuracy\":5}', 'published', '2026-08-27T23:59:46.000000Z', '2026-08-30T23:59:46.000000Z', NULL, '2026-08-30T21:12:19.000000Z', '2026-08-31T15:02:49.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3286', '150', 'problem', 'Mengapa Memilih Roster Minimalis Kualitas Cetak Padat Pengrajin?', '<p>Banyak produk loster di pasaran dibuat dengan adukan pasir kasar yang mudah rontok atau gompal saat dipasang. Membeli <strong>roster beton anti lumut</strong> langsung dari sentra pabrikasi pengrajin Plered menjamin keping roster yang dicetak padat, permukaannya halus, dan memiliki sudut siku presisi untuk keindahan jangka panjang rumah Anda.</p>', '1', '1', NULL, NULL, '2026-08-30T23:59:47.000000Z', '2026-08-30T23:59:47.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3287', '150', 'solution', 'Solusi Roster Minimalis IndoRoster: Presisi, Padat & 45+ Pilihan Motif', '<p>IndoRoster memproduksi aneka ragam roster minimalis arsitektural langsung dari sentra pengrajin Plered Purwakarta dengan standar kerapian tinggi. Kami mengelompokkan koleksi motif kami sesuai kebutuhan fungsional bangunan Anda:</p><ul><li><strong>Roster Anti-Tampias Hujan (Motif Nako LS & Nako Sipit):</strong> Dirancang dengan kemiringan sirip khusus yang efektif menghalau percikan air hujan agar tidak masuk ke dalam ruangan, sangat ideal untuk area balkon, ruang cuci jemur, dan dinding samping terbuka.</li><li><strong>Roster Karakter 3D & Signature (Motif Petir, MMC, Arrow, Batman):</strong> Memiliki permukaan timbul berdimensi yang memberikan tekstur tegas pada dinding fasad depan ruko, kafe, maupun rumah tinggal modern.</li><li><strong>Roster Minimalis Geometris (Motif JaboL, PCL, Kotak):</strong> Mengusung garis tegas sederhana yang selaras dengan arsitektur perumahan modern, menciptakan tampilan dinding yang bersih, rapi, dan simetris.</li><li><strong>Cetak Padat Rapi oleh Pengrajin:</strong> Setiap keping dicetak padat oleh tangan terampil pengrajin dengan sudut siku 90 derajat yang mempermudah tukang memasang dinding secara lurus dan presisi.</li></ul>', '2', '1', NULL, NULL, '2026-08-30T23:59:47.000000Z', '2026-08-30T23:59:47.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3288', '150', 'specs', 'Panduan Memilih Roster Beton Padat Anti Lumut & Jamur untuk Daerah Lembab', '<div class=\'grid grid-cols-1 md:grid-cols-3 gap-6\'><div class=\'p-6 rounded-2xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700\'><div class=\'text-2xl mb-2\'>📏</div><h4 class=\'font-bold text-slate-900 dark:text-white text-sm mb-2\'>1. Ukuran & Kebutuhan Dinding</h4><p class=\'text-xs text-slate-600 dark:text-slate-300 leading-relaxed\'>Ukuran modular 20×20 cm (isi 25 keping/m²). Rumus hitung: Luas Dinding (m²) × 25 pcs + 3–5% margin aman cadangan tukang.</p></div><div class=\'p-6 rounded-2xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700\'><div class=\'text-2xl mb-2\'>🧱</div><h4 class=\'font-bold text-slate-900 dark:text-white text-sm mb-2\'>2. Ketebalan 10cm vs 8cm</h4><p class=\'text-xs text-slate-600 dark:text-slate-300 leading-relaxed\'>Tebal 10 cm sangat kokoh untuk dinding pagar luar & fasad lantai 1. Tebal 8 cm lebih ringan untuk partisi ruangan & fasad atas.</p></div><div class=\'p-6 rounded-2xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700\'><div class=\'text-2xl mb-2\'>✨</div><h4 class=\'font-bold text-slate-900 dark:text-white text-sm mb-2\'>3. Pilihan Warna & Finishing</h4><p class=\'text-xs text-slate-600 dark:text-slate-300 leading-relaxed\'>Tersedia warna Abu Natural dan Semen Putih. Permukaan keping padat dan halus, siap diekspos natural atau dicat warna sesuai konsep.</p></div></div>', '3', '1', NULL, NULL, '2026-08-30T23:59:47.000000Z', '2026-08-30T23:59:47.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3289', '150', 'faq', 'Pertanyaan Umum Seputar Roster Beton Padat Anti Lumut & Jamur untuk Daerah Lembab', '<div class=\'space-y-4\'><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Berapa minimum pemesanan (MOQ) di IndoRoster?</strong><br>IndoRoster memberlakukan MOQ terverifikasi: Minimum 1.000 pcs untuk retail/pembelian awal dan 5.000 pcs untuk pengadaan proyek/grosir (berlaku merata untuk seluruh motif tanpa kecuali).</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Berapa keping roster yang dibutuhkan untuk 1 meter persegi dinding?</strong><br>Untuk ukuran standar 20×20 cm, dibutuhkan tepat 25 keping per 1 m² luas dinding. Kami sarankan menambah 3–5% sebagai margin aman cadangan potongan tukang.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Apakah ada garansi jika terdapat keping roster yang pecah di perjalanan?</strong><br>Ya, IndoRoster memberikan garansi penggantian keping baru 100% tanpa biaya tambahan jika ditemukan material yang rusak atau pecah saat pengiriman armada kami tiba di lokasi.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Apakah keping roster bisa langsung diekspos atau dicat?</strong><br>Bisa. Permukaan roster IndoRoster padat dan halus, sehingga dapat langsung diekspos dengan cairan pelapis coating bening atau dicat warna sesuai selera arsitektur Anda.</div><div class=\'p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 leading-relaxed text-slate-700 dark:text-slate-300 text-sm\'><strong>Bagaimana cara berkonsultasi dan mendapatkan penawaran harga resmi?</strong><br>Anda dapat langsung menghubungi tim penjualan kami melalui WhatsApp dengan menginformasikan motif yang dipilih, estimasi kebutuhan keping, serta alamat tujuan pengiriman.</div></div>', '4', '1', NULL, NULL, '2026-08-30T23:59:47.000000Z', '2026-08-30T23:59:47.000000Z');
REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('167', 'roster-beton', 'pillar', 'roster beton', '[\"pabrik roster beton\",\"supplier roster beton\",\"jual roster beton\",\"harga roster beton\",\"loster beton indonesia\",\"distributor roster beton\"]', 'bofu', 'umum', 'umum', NULL, NULL, NULL, 'Roster Beton Indonesia | Pabrik & Distributor Resmi — IndoRoster', 'Pusat produsen roster beton arsitektural kualitas cetak padat presisi harga pabrik Plered Purwakarta. Sedia 45+ motif modern, kirim cepat Jabodetabek & se-Indonesia.', NULL, NULL, NULL, NULL, '', 'Pabrik & Supplier Roster Beton Terlengkap di Indonesia', 'IndoRoster adalah pusat pabrikasi dan produsen tangan pertama material roster beton arsitektural berkualitas tinggi yang berakar dari sentra kerajinan Plered, Purwakarta. Kami menghadirkan standar baru ventilasi dinding modern yang mengombinasikan kekuatan struktural beton cetak padat kokoh, presisi sudut siku 90 derajat cetakan plat baja, serta keindahan visual fasad tropis kontemporer untuk hunian privat, gedung komersial, dan proyek residensial skala nasional.', 'Inovasi teknik cetak tumbuk semi-kering padat tinggi dengan toleransi dimensi mikro, menjamin dinding tegak lurus sempurna dan hemat adukan semen perekat.', 'Dipercaya oleh ribuan kontraktor, studio arsitek, dan pengembang perumahan dengan jaminan garansi penggantian 100% keping pecah langsung di lokasi proyek.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '98', NULL, 'published', '2026-08-31T14:53:13.000000Z', NULL, NULL, '2026-08-31T14:31:40.000000Z', '2026-08-31T15:02:50.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3299', '167', 'problem', 'Tantangan Memilih Roster Beton di Pasaran: Risiko Mutu & Kerugian Proyek', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Di pasaran bebas, banyak beredar roster beton curah hasil cetak cor basah manual yang diproduksi tanpa kontrol komposisi pasir dan semen yang terukur. Dampak buruk yang sering merugikan pemilik rumah dan kontraktor di antaranya:</p>
                <div class=\"space-y-3.5 not-prose\">
                    <div class=\"flex items-start gap-3 p-4 rounded-2xl bg-rose-50/60 dark:bg-rose-950/30 border border-rose-200/60 dark:border-rose-900/40\">
                        <span class=\"text-rose-500 text-lg flex-shrink-0 mt-0.5\">❌</span>
                        <div>
                            <strong class=\"text-sm font-bold text-slate-900 dark:text-white block\">Struktur Keropos & Mudah Gompal</strong>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-0.5\">Campuran pasir kasar yang tidak dipadatkan dengan tekanan memadai membuat keping roster rapuh, mudah patah di bagian ornamen lubang, dan rontok saat ditumpuk atau dipasang tukang.</p>
                        </div>
                    </div>
                    <div class=\"flex items-start gap-3 p-4 rounded-2xl bg-rose-50/60 dark:bg-rose-950/30 border border-rose-200/60 dark:border-rose-900/40\">
                        <span class=\"text-rose-500 text-lg flex-shrink-0 mt-0.5\">❌</span>
                        <div>
                            <strong class=\"text-sm font-bold text-slate-900 dark:text-white block\">Sudut Miring & Nat Semen Bergelombang</strong>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-0.5\">Cetakan kayu atau plat tipis yang melengkung menghasilkan ketebalan keping yang tidak seragam (selisih 3–7 mm), memaksa tukang memakai spesi semen tebal yang membuat hasil akhir dinding bergelombang dan tidak sedap dipandang.</p>
                        </div>
                    </div>
                    <div class=\"flex items-start gap-3 p-4 rounded-2xl bg-rose-50/60 dark:bg-rose-950/30 border border-rose-200/60 dark:border-rose-900/40\">
                        <span class=\"text-rose-500 text-lg flex-shrink-0 mt-0.5\">❌</span>
                        <div>
                            <strong class=\"text-sm font-bold text-slate-900 dark:text-white block\">Pori Kasar Menyerap Air & Jamur Hitam</strong>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-0.5\">Roster tanpa formulasi padat memiliki daya serap air (porositas) sangat tinggi, sehingga saat musim hujan air meresap ke dalam dinding dan memicu pertumbuhan lumut hitam serta kerak jamur yang merusak cat.</p>
                        </div>
                    </div>
                </div>', '1', '1', NULL, NULL, '2026-08-31T14:53:14.000000Z', '2026-08-31T14:53:14.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3300', '167', 'solution', 'Standar Mutu Pabrik IndoRoster: Presisi Plat Baja & Kepadatan Maksimal', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">IndoRoster menjawab tantangan tersebut dengan menerapkan proses manufaktur terstandarisasi di sentra Plered Purwakarta:</p>
                <div class=\"space-y-3.5 not-prose\">
                    <div class=\"flex items-start gap-3 p-4 rounded-2xl bg-emerald-50/60 dark:bg-emerald-950/30 border border-emerald-200/60 dark:border-emerald-900/40\">
                        <span class=\"text-emerald-500 text-lg flex-shrink-0 mt-0.5\">✅</span>
                        <div>
                            <strong class=\"text-sm font-bold text-slate-900 dark:text-white block\">Cetak Tumbuk Semi-Kering Berdensitas Tinggi</strong>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-0.5\">Campuran semen mutu tinggi dan pasir abu batu ayak bergradasi halus dipadatkan dengan teknik tumbuk bertenaga tinggi, menghasilkan bobot solid 3.8 – 4.2 kg per keping dengan daya tahan benturan yang sangat kokoh.</p>
                        </div>
                    </div>
                    <div class=\"flex items-start gap-3 p-4 rounded-2xl bg-emerald-50/60 dark:bg-emerald-950/30 border border-emerald-200/60 dark:border-emerald-900/40\">
                        <span class=\"text-emerald-500 text-lg flex-shrink-0 mt-0.5\">✅</span>
                        <div>
                            <strong class=\"text-sm font-bold text-slate-900 dark:text-white block\">Akurasi Siku 90° Matras Plat Baja Presisi</strong>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-0.5\">Menggunakan cetakan plat baja tebal yang dikalibrasi berkala sehingga setiap keping memiliki dimensi modular 20×20×10 cm yang simetris, menghasilkan garis nat vertikal dan horizontal yang lurus rapi tanpa perlu perataan tebal.</p>
                        </div>
                    </div>
                    <div class=\"flex items-start gap-3 p-4 rounded-2xl bg-emerald-50/60 dark:bg-emerald-950/30 border border-emerald-200/60 dark:border-emerald-900/40\">
                        <span class=\"text-emerald-500 text-lg flex-shrink-0 mt-0.5\">✅</span>
                        <div>
                            <strong class=\"text-sm font-bold text-slate-900 dark:text-white block\">Permukaan Halus Siap Ekspos / Finishing Cat</strong>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-0.5\">Kerapatan partikel mineral membuat pori-pori permukaan keping tertutup rapat, tahan terhadap rembesan air hujan, anti-lumut, dan langsung siap diekspos natural atau dicat warna sesuai konsep arsitektur.</p>
                        </div>
                    </div>
                </div>', '2', '1', NULL, NULL, '2026-08-31T14:53:14.000000Z', '2026-08-31T15:11:32.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3301', '167', 'specs', 'Spesifikasi Teknis & Panduan Desain Modular Dinding Roster', '<div class=\"grid grid-cols-1 md:grid-cols-3 gap-6 not-prose\">
                    <div class=\"p-6 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                        <div class=\"w-12 h-12 rounded-2xl bg-terra-500/10 text-terra-600 dark:text-terra-400 flex items-center justify-center text-2xl font-bold mb-4\">📐</div>
                        <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-2\">Dimensi & Rasio Volume</h4>
                        <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">Ukuran standar modular <strong>20 × 20 × 10 cm</strong>. Menghasilkan tepat <strong>25 keping per 1 m²</strong> luas dinding. Rumus estimasi: Luas Bidang (m²) × 25 pcs + 3–5% cadangan potongan nat sudut tukang.</p>
                    </div>
                    <div class=\"p-6 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                        <div class=\"w-12 h-12 rounded-2xl bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 flex items-center justify-center text-2xl font-bold mb-4\">⚖️</div>
                        <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-2\">Mutu Beton & Kepadatan</h4>
                        <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">Bobot rata-rata <strong>3.8 – 4.2 kg per keping</strong>. Kuat tekan setara beton struktural padat kokoh. Sangat aman dan stabil untuk konstruksi dinding pagar keliling luar maupun secondary skin fasad lantai 2–3.</p>
                    </div>
                    <div class=\"p-6 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                        <div class=\"w-12 h-12 rounded-2xl bg-amber-500/10 text-amber-600 dark:text-amber-400 flex items-center justify-center text-2xl font-bold mb-4\">🚚</div>
                        <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-2\">Armada Kirim & Garansi</h4>
                        <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">Pengiriman langsung armada pabrik (Colt Diesel & Fuso) ke wilayah Jabodetabek, Jawa Barat, dan sekitarnya dengan jaminan <strong>100% garansi ganti keping baru di tempat</strong> jika ditemukan retak saat tiba.</p>
                    </div>
                </div>', '3', '1', NULL, NULL, '2026-08-31T14:53:14.000000Z', '2026-08-31T15:02:51.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3302', '167', 'faq', 'Tanya Jawab Seputar Roster Beton IndoRoster', '<div class=\"space-y-4\">
                    <div class=\"p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 text-sm\">
                        <strong class=\"text-slate-900 dark:text-white font-bold block mb-1\">Apakah IndoRoster melayani pemesanan eceran untuk renovasi rumah pribadi?</strong>
                        <span class=\"text-slate-600 dark:text-slate-300\">Tentu saja! Kami melayani pembelian eceran mulai dari puluhan pcs untuk renovasi dinding teras atau pagar rumah, hingga pesanan puluhan ribu pcs untuk pengadaan proyek perumahan developer dan kontraktor.</span>
                    </div>
                    <div class=\"p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 text-sm\">
                        <strong class=\"text-slate-900 dark:text-white font-bold block mb-1\">Bagaimana cara menghitung kebutuhan roster untuk bidang dinding saya?</strong>
                        <span class=\"text-slate-600 dark:text-slate-300\">Cukup ukur panjang × tinggi dinding untuk mengetahui luas meter persegi (m²), kemudian kalikan dengan 25 pcs. Anda juga bisa langsung menggunakan fitur <a href=\"/kalkulator-roster\" class=\"text-terra-600 dark:text-terra-400 font-bold underline\">Kalkulator Roster IndoRoster</a> atau berkonsultasi dengan tim teknis kami via WhatsApp.</span>
                    </div>
                    <div class=\"p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 text-sm\">
                        <strong class=\"text-slate-900 dark:text-white font-bold block mb-1\">Apa jaminan jika terdapat keping roster yang pecah saat pengiriman?</strong>
                        <span class=\"text-slate-600 dark:text-slate-300\">Kami memberikan Garansi 100% Ganti Baru di tempat. Tim logistik armada kami akan langsung mengganti keping yang rusak tanpa membebankan biaya tambahan sepeser pun.</span>
                    </div>
                </div>', '4', '1', NULL, NULL, '2026-08-31T14:53:14.000000Z', '2026-08-31T14:53:14.000000Z');
REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('168', 'roster-minimalis', 'pillar', 'roster minimalis', '[\"roster minimalis modern\",\"motif roster minimalis\",\"harga roster minimalis\",\"loster minimalis rumah\",\"roster pagar minimalis\",\"roster nako anti tampias\"]', 'bofu', 'umum', 'umum', NULL, NULL, NULL, 'Roster Minimalis Modern | Motif Elegan Fasad & Pagar — IndoRoster', 'Koleksi lengkap loster & roster minimalis modern motif geometris, nako, dan 3D. Mutu cetak padat presisi tanpa pori kasar, garansi aman kirim langsung pabrik.', NULL, NULL, NULL, NULL, '', 'Koleksi Roster Minimalis Modern untuk Fasad, Pagar & Partisi', 'Ciptakan karakter hunian tropis modern yang sejuk, estetik, dan bernilai seni tinggi bersama koleksi roster minimalis IndoRoster. Menawarkan lebih dari 45 ragam motif eksklusif — mulai dari pola geometris bersih, motif jalusi nako anti tampias, hingga motif 3D sculptural timbul — setiap keping dirancang proporsional untuk menyatu sempurna dengan gaya arsitektur Japandi, Industrial, Tropis Modern, dan Skandinavia.', 'Kombinasi fungsi aerodinamis sirkulasi udara maksimal dengan estetika visual bayangan cahaya matahari yang artistik pada dinding ruangan Anda.', 'Menjadi pilihan favorit para arsitek ternama di Jabodetabek dan Bandung untuk proyek fasad villa, kafe aesthetic, dan perumahan klaster modern.', NULL, 'whatsapp', 'Pilih Motif Roster Minimalis via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '98', NULL, 'published', '2026-08-31T14:53:13.000000Z', NULL, NULL, '2026-08-31T14:32:12.000000Z', '2026-08-31T14:53:14.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3303', '168', 'problem', 'Masalah Desain Fasad Tertutup: Rumah Pengap & Boros Listrik Pendingin Ruangan', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Membangun rumah di iklim tropis Indonesia dengan dinding bata masif tertutup sering kali menimbulkan masalah kenyamanan jangka panjang:</p>
                <div class=\"space-y-3.5 not-prose\">
                    <div class=\"flex items-start gap-3 p-4 rounded-2xl bg-rose-50/60 dark:bg-rose-950/30 border border-rose-200/60 dark:border-rose-900/40\">
                        <span class=\"text-rose-500 text-lg flex-shrink-0 mt-0.5\">⚠️</span>
                        <div>
                            <strong class=\"text-sm font-bold text-slate-900 dark:text-white block\">Suhu Dalam Rumah Panas & Terjebak</strong>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-0.5\">Dinding masif menyerap panas matahari siang hari dan melepaskannya ke dalam ruangan pada malam hari, membuat rumah terasa pengap dan memaksa AC bekerja tanpa henti.</p>
                        </div>
                    </div>
                    <div class=\"flex items-start gap-3 p-4 rounded-2xl bg-rose-50/60 dark:bg-rose-950/30 border border-rose-200/60 dark:border-rose-900/40\">
                        <span class=\"text-rose-500 text-lg flex-shrink-0 mt-0.5\">⚠️</span>
                        <div>
                            <strong class=\"text-sm font-bold text-slate-900 dark:text-white block\">Ruangan Gelap & Lembab</strong>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-0.5\">Minimnya celah bukaan alami membuat area tangga, ruang keluarga, dan void dapur kurang mendapatkan pencahayaan matahari, sehingga lampu harus menyala sepanjang hari.</p>
                        </div>
                    </div>
                </div>', '1', '1', NULL, NULL, '2026-08-31T14:53:14.000000Z', '2026-08-31T14:53:14.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3304', '168', 'solution', 'Solusi Fasad Roster Minimalis: Sirkulasi Alami & Estetika Tropis Modern', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Pemasangan roster minimalis IndoRoster memberikan transformasi ganda pada arsitektur bangunan Anda:</p>
                <div class=\"space-y-3.5 not-prose\">
                    <div class=\"flex items-start gap-3 p-4 rounded-2xl bg-emerald-50/60 dark:bg-emerald-950/30 border border-emerald-200/60 dark:border-emerald-900/40\">
                        <span class=\"text-emerald-500 text-lg flex-shrink-0 mt-0.5\">✨</span>
                        <div>
                            <strong class=\"text-sm font-bold text-slate-900 dark:text-white block\">Secondary Skin Meredam Panas Hingga 40%</strong>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-0.5\">Dinding roster berfungsi sebagai pelindung (secondary skin) yang memecah paparan radiasi matahari langsung ke kaca dan dinding utama, sekaligus mengalirkan hembusan angin sejuk secara kontinu.</p>
                        </div>
                    </div>
                    <div class=\"flex items-start gap-3 p-4 rounded-2xl bg-emerald-50/60 dark:bg-emerald-950/30 border border-emerald-200/60 dark:border-emerald-900/40\">
                        <span class=\"text-emerald-500 text-lg flex-shrink-0 mt-0.5\">✨</span>
                        <div>
                            <strong class=\"text-sm font-bold text-slate-900 dark:text-white block\">Privasi Maksimal Tanpa Kesan Terkurung</strong>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-0.5\">Bukaan geometris memberikan privasi aman dari pandangan luar, namun penghuni di dalam tetap leluasa menikmati sirkulasi udara bebas dan pencahayaan alami yang lembut.</p>
                        </div>
                    </div>
                </div>', '2', '1', NULL, NULL, '2026-08-31T14:53:14.000000Z', '2026-08-31T14:53:14.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3305', '168', 'specs', 'Inspirasi Penerapan Roster Minimalis pada Berbagai Bagian Hunian', '<div class=\"grid grid-cols-1 md:grid-cols-3 gap-6 not-prose\">
                    <div class=\"p-6 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                        <div class=\"w-12 h-12 rounded-2xl bg-terra-500/10 text-terra-600 dark:text-terra-400 flex items-center justify-center text-2xl font-bold mb-4\">🏡</div>
                        <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-2\">Pagar Rumah Minimalis</h4>
                        <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">Memberikan pembatas halaman yang kokoh dan berwibawa tanpa membuat tampak depan rumah terasa kaku, gelap, atau sumpek.</p>
                    </div>
                    <div class=\"p-6 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                        <div class=\"w-12 h-12 rounded-2xl bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 flex items-center justify-center text-2xl font-bold mb-4\">🏢</div>
                        <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-2\">Fasad Secondary Skin</h4>
                        <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">Aksen visual lantai 2 yang spektakuler. Menciptakan permainan bayangan matahari (shadow play) yang memukau di interior lantai atas.</p>
                    </div>
                    <div class=\"p-6 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                        <div class=\"w-12 h-12 rounded-2xl bg-amber-500/10 text-amber-600 dark:text-amber-400 flex items-center justify-center text-2xl font-bold mb-4\">🛋️</div>
                        <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-2\">Partisi & Sekat Ruang</h4>
                        <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">Penyekat semi-transparan antara ruang tamu dan ruang keluarga yang membuat hunian terasa lebih luas, elegan, dan estetik.</p>
                    </div>
                </div>', '3', '1', NULL, NULL, '2026-08-31T14:53:14.000000Z', '2026-08-31T14:53:14.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3306', '168', 'faq', 'Tanya Jawab Seputar Koleksi Roster Minimalis', '<div class=\"space-y-4\">
                    <div class=\"p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 text-sm\">
                        <strong class=\"text-slate-900 dark:text-white font-bold block mb-1\">Apakah roster minimalis motif nako benar-benar anti-tampias saat hujan deras?</strong>
                        <span class=\"text-slate-600 dark:text-slate-300\">Ya. Varian motif nako dirancang dengan kemiringan sirip khusus yang mengarahkan tetesan air hujan jatuh ke luar, sehingga angin tetap masuk bebas tanpa membawa percikan air ke dalam ruangan.</span>
                    </div>
                    <div class=\"p-5 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60 text-sm\">
                        <strong class=\"text-slate-900 dark:text-white font-bold block mb-1\">Bisa pesan sampel fisik sebelum order volume banyak?</strong>
                        <span class=\"text-slate-600 dark:text-slate-300\">Bisa sekali. Kami siap mengirimkan sampel fisik keping roster ke kantor arsitek, studio desain, maupun alamat pemilik rumah.</span>
                    </div>
                </div>', '4', '1', NULL, NULL, '2026-08-31T14:53:14.000000Z', '2026-08-31T14:53:14.000000Z');
REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('177', 'roster-beton-untuk-villa-resort', 'project', 'roster beton untuk villa resort', '[\"desain dinding roster villa\",\"roster arsitektur villa tropis\",\"partisi loster villa estetik\"]', 'bofu', 'arsitek', 'villa', NULL, NULL, NULL, 'Roster Beton untuk Villa & Resort Tropis | Pabrik IndoRoster', 'Produsen roster beton arsitektural untuk fasad & sekat villa resort tropis. Material cetak padat kokoh pasir abu batu, sejuk alami dan anti-lumut.', NULL, NULL, NULL, NULL, '', 'Roster Beton Arsitektural untuk Fasad & Dinding Villa Resort', 'Hadirkan atmosfer peristirahatan tropis yang mewah, tenang, dan menyatu dengan alam melalui sentuhan roster beton arsitektural IndoRoster. Dirancang khusus untuk arsitektur villa modern, resort pegunungan, dan private pavilion, roster kami memaksimalkan aliran angin sejuk pegunungan sekaligus membingkai pemandangan lanskap hijau tanpa mengorbankan privasi tamu.', 'Material padat berpori rapat yang tahan terhadap kelembaban udara dataran tinggi dan bebas dari pertumbuhan jamur kerak hitam.', 'Telah diaplikasikan di berbagai proyek villa eksklusif di Lembang, Puncak Bogor, Sukabumi, dan kawasan pesisir tropis.', NULL, 'whatsapp', 'Konsultasi Desain Villa via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '98', NULL, 'published', '2026-08-31T15:33:16.000000Z', NULL, NULL, '2026-08-31T15:33:16.000000Z', '2026-08-31T15:33:16.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3326', '177', 'problem', 'Tantangan Desain Dinding Villa: Kelembaban Tinggi & Risiko Lumut Hitam', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Membangun villa di kawasan berhawa sejuk atau dekat alam terbuka sering kali dihadapkan pada masalah cuaca ekstrem:</p>
                <div class=\"space-y-3.5 not-prose\">
                    <div class=\"flex items-start gap-3 p-4 rounded-2xl bg-rose-50/60 dark:bg-rose-950/30 border border-rose-200/60 dark:border-rose-900/40\">
                        <span class=\"text-rose-500 text-lg flex-shrink-0 mt-0.5\">⚠️</span>
                        <div>
                            <strong class=\"text-sm font-bold text-slate-900 dark:text-white block\">Dinding Cepat Berkerak Lumut</strong>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-0.5\">Roster pasaran yang berpori kasar menyerap embun pagi dan air hujan, memicu kerak lumut hitam yang merusak estetika kemewahan villa.</p>
                        </div>
                    </div>
                    <div class=\"flex items-start gap-3 p-4 rounded-2xl bg-rose-50/60 dark:bg-rose-950/30 border border-rose-200/60 dark:border-rose-900/40\">
                        <span class=\"text-rose-500 text-lg flex-shrink-0 mt-0.5\">⚠️</span>
                        <div>
                            <strong class=\"text-sm font-bold text-slate-900 dark:text-white block\">Sirkulasi Udara Terhambat Dinding Masif</strong>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-0.5\">Dinding bata tertutup membatasi aliran angin segar pegunungan, membuat interior terasa pengap dan lembab saat villa tidak dihuni.</p>
                        </div>
                    </div>
                </div>', '1', '1', NULL, NULL, '2026-08-31T15:33:16.000000Z', '2026-08-31T15:33:16.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3327', '177', 'solution', 'Solusi Dinding Bernafas IndoRoster: Estetik, Sejuk & Tahan Cuaca Tropis', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">IndoRoster menghadirkan material loster cetak tumbuk padat matras plat baja presisi untuk kesempurnaan villa Anda:</p>
                <div class=\"space-y-3.5 not-prose\">
                    <div class=\"flex items-start gap-3 p-4 rounded-2xl bg-emerald-50/60 dark:bg-emerald-950/30 border border-emerald-200/60 dark:border-emerald-900/40\">
                        <span class=\"text-emerald-500 text-lg flex-shrink-0 mt-0.5\">✨</span>
                        <div>
                            <strong class=\"text-sm font-bold text-slate-900 dark:text-white block\">Pori Rapat Kedap Jamur & Tahan Lembab</strong>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-0.5\">Kepadatan partikel pasir abu batu murni membuat permukaan keping tidak mudah menyerap air hujan, menjaga tampilan dinding tetap bersih elegan.</p>
                        </div>
                    </div>
                    <div class=\"flex items-start gap-3 p-4 rounded-2xl bg-emerald-50/60 dark:bg-emerald-950/30 border border-emerald-200/60 dark:border-emerald-900/40\">
                        <span class=\"text-emerald-500 text-lg flex-shrink-0 mt-0.5\">✨</span>
                        <div>
                            <strong class=\"text-sm font-bold text-slate-900 dark:text-white block\">Shadow Play Artistik untuk Spot Foto Instagramable</strong>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-0.5\">Pola bukaan geometris dan floral menciptakan bayangan sinar matahari yang dinamis pada lantai dan kolam renang villa.</p>
                        </div>
                    </div>
                </div>', '2', '1', NULL, NULL, '2026-08-31T15:33:16.000000Z', '2026-08-31T15:33:16.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3328', '177', 'specs', 'Rekomendasi Pola & Modul Dinding untuk Area Villa', '<div class=\"grid grid-cols-1 md:grid-cols-3 gap-6 not-prose\">
                    <div class=\"p-6 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                        <div class=\"text-2xl mb-2\">🏊</div>
                        <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">Sekat Kolam Renang</h4>
                        <p class=\"text-xs text-slate-600 dark:text-slate-300\">Memberikan privasi saat berenang tanpa memblokir hembusan angin segar taman.</p>
                    </div>
                    <div class=\"p-6 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                        <div class=\"text-2xl mb-2\">🛁</div>
                        <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">Semi-Outdoor Bathroom</h4>
                        <p class=\"text-xs text-slate-600 dark:text-slate-300\">Pencahayaan alami dan ventilasi bebas lembab untuk kamar mandi bergaya resort Bali.</p>
                    </div>
                    <div class=\"p-6 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                        <div class=\"text-2xl mb-2\">🌿</div>
                        <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">Balkon Fasad Lantai 2</h4>
                        <p class=\"text-xs text-slate-600 dark:text-slate-300\">Pagar pengaman balkon yang estetik dengan modul standar 20×20×10 cm (25 pcs/m²).</p>
                    </div>
                </div>', '3', '1', NULL, NULL, '2026-08-31T15:33:16.000000Z', '2026-08-31T15:33:16.000000Z');
REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('178', 'roster-beton-untuk-cafe-industrial', 'project', 'roster beton cafe aesthetic', '[\"fasad roster cafe industrial aesthetic\",\"dinding roster kedai kopi\",\"partisi roster cafe kekinian\"]', 'bofu', 'arsitek', 'cafe', NULL, NULL, NULL, 'Roster Beton untuk Cafe & Restoran Aesthetic | Pabrik IndoRoster', 'Koleksi roster beton aesthetic motif geometris & raw industrial untuk fasad kafe dan partisi interior kedai kopi. Harga pabrik langsung sentra Plered.', NULL, NULL, NULL, NULL, '', 'Roster Beton Aesthetic untuk Fasad & Interior Cafe Industrial', 'Ciptakan ambience kedai kopi kekinian yang berkarakter kuat, estetik, dan instagramable bersama koleksi roster beton IndoRoster. Tekstur abu natural dari olahan pasir abu batu murni memberikan sentuhan raw industrial yang autentik, berpadu sempurna dengan pencahayaan warm white lampu kafe untuk menghasilkan latar foto yang memikat pengunjung.', 'Kombinasi motif geometris modern dengan ketahanan benturan tinggi untuk area komersial berintensitas pengunjung padat.', 'Telah dipercaya oleh puluhan brand coffee shop dan restoran di Jakarta Selatan, Bandung, Bekasi, dan Tangerang.', NULL, 'whatsapp', 'Dapatkan Penawaran Desain Cafe via WA', NULL, NULL, NULL, NULL, NULL, NULL, '0', '97', NULL, 'published', '2026-08-31T15:33:16.000000Z', NULL, NULL, '2026-08-31T15:33:16.000000Z', '2026-08-31T15:33:16.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3329', '178', 'problem', 'Tantangan Desain Kafe: Dinding Monoton & Biaya Dekorasi Mahal', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Banyak pemilik kafe menghabiskan anggaran besar untuk dekorasi interior sementara fasad luar tampak biasa saja:</p>
                <div class=\"space-y-3.5 not-prose\">
                    <div class=\"flex items-start gap-3 p-4 rounded-2xl bg-rose-50/60 dark:bg-rose-950/30 border border-rose-200/60 dark:border-rose-900/40\">
                        <span class=\"text-rose-500 text-lg flex-shrink-0 mt-0.5\">⚠️</span>
                        <div>
                            <strong class=\"text-sm font-bold text-slate-900 dark:text-white block\">Tampilan Fasad Kurang Eye-Catching</strong>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-0.5\">Fasad dinding datar tidak menarik perhatian pengguna jalan, sehingga potensi mendatangkan pelanggan baru berkurang.</p>
                        </div>
                    </div>
                </div>', '1', '1', NULL, NULL, '2026-08-31T15:33:17.000000Z', '2026-08-31T15:33:17.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3330', '178', 'solution', 'Solusi Fasad Roster: Ikonik, Murah Perawatan & Spot Foto Favorit', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Roster beton IndoRoster memberikan focal point arsitektural yang tahan lama tanpa perlu biaya perawatan rutin yang mahal.</p>', '2', '1', NULL, NULL, '2026-08-31T15:33:17.000000Z', '2026-08-31T15:33:17.000000Z');
REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('179', 'roster-beton-untuk-fasad-ruko', 'project', 'fasad roster ruko modern', '[\"dinding roster bangunan komersial\",\"secondary skin ruko roster\",\"roster ventilasi ruko\"]', 'bofu', 'kontraktor', 'ruko', NULL, NULL, NULL, 'Fasad Roster Ruko Modern & Bangunan Komersial — IndoRoster', 'Transformasi tampilan ruko komersial dengan secondary skin roster beton presisi siku 90°. Hemat listrik pendingin ruangan, sirkulasi lancar dan tampak mewah.', NULL, NULL, NULL, NULL, '', 'Secondary Skin & Fasad Roster Beton untuk Ruko Modern', 'Ubah tampilan ruko komersial standar menjadi bangunan usaha yang megah dan berkelas modern. Aplikasi dinding roster pada fasad lantai 2 dan 3 ruko berfungsi ganda: sebagai identitas visual bisnis yang prestisius sekaligus pelindung panas sinar matahari langsung ke dinding kaca kantor.', 'Mereduksi panas matahari pada ruang kantor lantai atas ruko hingga 40%, menjaga ruangan tetap sejuk dan menghemat tagihan listrik.', 'Mensuplai proyek renovasi fasad ruko perkantoran di kawasan segitiga emas bisnis Jakarta dan sekitarnya.', NULL, 'whatsapp', 'Konsultasi Fasad Ruko via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '96', NULL, 'published', '2026-08-31T15:33:16.000000Z', NULL, NULL, '2026-08-31T15:33:17.000000Z', '2026-08-31T15:33:17.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3331', '179', 'solution', 'Keuntungan Secondary Skin Roster pada Bangunan Ruko Komersial', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Pemasangan dinding roster pada fasad luar ruko memberikan efisiensi operasional dan peningkatan nilai properti usaha Anda secara signifikan.</p>', '1', '1', NULL, NULL, '2026-08-31T15:33:17.000000Z', '2026-08-31T15:33:17.000000Z');
REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('180', 'roster-pagar-rumah-minimalis', 'usecase', 'pagar roster minimalis modern', '[\"desain pagar roster beton modern\",\"pagar rumah roster abu batu\",\"pagar loster rumah tropis\"]', 'bofu', 'umum', 'residensial', NULL, NULL, NULL, 'Desain Pagar Roster Minimalis Modern & Kokoh — IndoRoster', 'Inspirasi desain pagar roster beton minimalis modern dari pabrik IndoRoster. Kuat padat 3.8-4.2 kg, sirkulasi udara lancar, dan aman menjaga privasi.', NULL, NULL, NULL, NULL, '', 'Pagar Roster Minimalis: Kokoh, Sejuk & Estetik untuk Rumah Anda', 'Tinggalkan pagar tembok masif yang kaku dan gelap. Pagar roster minimalis IndoRoster menghadirkan batas halaman yang kokoh berwibawa, mengalirkan sirkulasi angin segar ke taman depan, serta menjaga privasi keluarga dari pandangan jalan raya secara proporsional.', 'Material padat cetak tumbuk berbobot mantap 3.8–4.2 kg per keping, aman menahan benturan dan cuaca terik hujan.', 'Menjadi pilihan utama ribuan pemilik rumah tinggal di Jabodetabek dan Jawa Barat untuk pagar depan rumah tropis modern.', NULL, 'whatsapp', 'Hitung Kebutuhan Pagar via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '98', NULL, 'published', '2026-08-31T15:33:16.000000Z', NULL, NULL, '2026-08-31T15:33:17.000000Z', '2026-08-31T15:33:17.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3332', '180', 'problem', 'Masalah Pagar Tembok Masif Tertutup', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Pagar tembok bata yang tertutup rapat membuat area teras rumah terasa sumpek, tanaman depan rumah kekurangan sirkulasi udara, dan fasad rumah terlihat terisolasi dari lingkungan sekitar.</p>', '1', '1', NULL, NULL, '2026-08-31T15:33:17.000000Z', '2026-08-31T15:33:17.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3333', '180', 'solution', 'Kombinasi Sempurna Privasi & Angin Segar', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Pagar roster IndoRoster memberikan perpaduan ideal antara keamanan struktural, privasi visual, dan estetika arsitektur tropis kekinian.</p>', '2', '1', NULL, NULL, '2026-08-31T15:33:17.000000Z', '2026-08-31T15:33:17.000000Z');
