REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('3334', '181', 'solution', 'Efisiensi Energi & Keindahan Visual Secondary Skin IndoRoster', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Dinding roster sebagai secondary skin memberikan solusi pasif pendinginan bangunan yang ramah lingkungan dan tahan lama hingga puluhan tahun tanpa perawatan rumit.</p>', '1', '1', NULL, NULL, '2026-08-31T15:33:18.000000Z', '2026-08-31T15:33:18.000000Z');
