REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('186', 'harga-roster-beton-partai-besar', 'wholesale', 'harga roster beton partai besar', '[\"harga grosir roster beton pabrik\",\"diskon roster beton volume besar\",\"jual roster beton per truk ritase\"]', 'bofu', 'kontraktor', 'umum', NULL, NULL, NULL, 'Harga Roster Beton Partai Besar & Grosir Pabrik — IndoRoster', 'Dapatkan penawaran harga roster beton partai besar tangan pertama pabrik Plered Purwakarta. Skema harga bertingkat khusus pemborong & distributor.', NULL, NULL, NULL, NULL, '', 'Harga Roster Beton Partai Besar: Grosir Langsung Tangan Pertama Pabrik', 'Bagi kontraktor, pemborong, toko bangunan, dan distributor yang membutuhkan material roster beton dalam volume ratusan hingga puluhan ribu keping, IndoRoster menawarkan skema harga grosir pabrik yang sangat kompetitif dengan sistem ritase truk Colt Diesel dan Fuso langsung ke lokasi gudang/proyek Anda.', 'Harga tangan pertama langsung dari sentra Plered tanpa potongan perantara, memaksimalkan efisiensi anggaran belanja proyek Anda.', 'Melayani pengiriman rutin mingguan dan bulanan untuk jaringan toko material dan proyek skala besar se-Indonesia.', NULL, 'whatsapp', 'Minta Skema Harga Grosir via WA', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T15:33:16.000000Z', NULL, NULL, '2026-08-31T15:33:19.000000Z', '2026-08-31T1