REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('214', 'loster-beton-2-sisi-bolak-balik', 'pillar', 'loster beton 2 sisi bolak balik', '[\"jual loster beton 2 sisi bolak balik\",\"harga loster beton 2 sisi bolak balik per keping\",\"supplier loster beton 2 sisi bolak balik pabrik plered\",\"distributor loster beton 2 sisi bolak balik jabodetabek\",\"ventilasi loster beton 2 sisi bolak balik rumah minimalis\",\"kisi kisi loster beton 2 sisi bolak balik dinding modern\"]', 'bofu', 'umum', 'residensial', NULL, NULL, NULL, 'Loster Beton 2 Sisi Bolak Balik — Standar Kualitas IndoRoster | Pabrik IndoRoster', 'Pusat produsen loster beton 2 sisi bolak balik kualitas cetak padat presisi plat baja siku 90°. Bahan pasir abu batu murni, tahan lumut & garansi aman kirim pa', NULL, NULL, NULL, NULL, '', 'Loster Beton 2 Sisi Bolak Balik — Standar Kualitas IndoRoster', 'Mewujudkan bangunan tropis yang sejuk, estetik, dan berdaya tahan puluhan tahun membutuhkan material dinding ventilasi berkualitas tinggi. Dalam pembahasan mengenai loster beton 2 sisi bolak balik, IndoRoster hadir sebagai produsen terpercaya dari sentra kerajinan Plered Purwakarta. Kami memadukan formula agregat pasir abu batu murni pilihan dengan teknik cetak tumbuk semi-kering bertenaga tinggi, menghasilkan keping loster berbobot padat 3.8–4.2 kg, berpori rapat anti-lumut, serta bersudut siku 90 derajat yang presisi untuk kesempurnaan dinding rumah Anda.', 'Teknik cetak tumbuk padat plat baja siku 90° presisi, menghemat adukan semen perekat tukang hingga 30% dan menghasilkan dinding yang tegak lurus sempurna.', 'Dipercaya oleh ribuan pemilik rumah tinggal, kontraktor tender, dan arsitek di Jabodetabek serta Jawa Barat dengan garansi penggantian 100% keping baru di lokasi proyek.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T16:00:12.000000Z', NULL, NULL, '2026-08-31T15:51:37.000000Z', '2026-08-31T16:00:12.000000Z');
