REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('4965', '273', 'solution', 'SOP Tata Muat Standar Pabrik & Garansi Penggantian di Lokasi', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Setiap keping loster disusun dengan bantalan pengaman dan pengikatan ketat oleh tim logistik kami. Keping yang mengalami retak atau pecah saat tiba akan langsung diganti baru di tempat oleh kru kami.</p>', '2', '1', NULL, NULL, '2026-08-31T16:00:13.000000Z', '2026-08-31T16:00:13.000000Z');
