REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('290', 'breeze-block-indonesia', 'project', 'breeze block indonesia', '[\"jual breeze block indonesia\",\"harga breeze block indonesia per keping\",\"supplier breeze block indonesia pabrik plered\",\"distributor breeze block indonesia jabodetabek\",\"ventilasi breeze block indonesia rumah minimalis\",\"kisi kisi breeze block indonesia dinding modern\"]', 'bofu', 'arsitek', 'residensial', NULL, NULL, NULL, 'Breeze Block Indonesia — Standar Kualitas IndoRoster | Pabrik IndoRoster', 'Pusat produsen breeze block indonesia kualitas cetak padat presisi plat baja siku 90°. Bahan pasir abu batu murni, tahan lumut & garansi aman kirim pabrik.', NULL, NULL, NULL, NULL, '', 'Breeze Block Indonesia — Standar Kualitas IndoRoster', 'Bagi kalangan studio arsitektur kontemporer dan desainer interior, konsep breeze block bukan sekadar lubang ventilasi, melainkan media eksplorasi bayangan shadow play, pencahayaan alami bergradasi, dan tekstur dinding arsitektural berskala tinggi. Koleksi breeze block indonesia dari IndoRoster diproduksi dengan matras plat baja presisi tinggi, menghasilkan tepian siku 90 derajat yang tajam, permukaan padat bebas retak rambut, dan fleksibilitas pola susun staggered maupun grid aligned yang spektakuler.', 'Teknik cetak tumbuk padat plat baja siku 90° presisi, menghemat adukan semen perekat tukang hingga 30% dan menghasilkan dinding yang tegak lurus sempurna.', 'Dipercaya oleh ribuan pemilik rumah tinggal, kontraktor tender, dan arsitek di Jabodetabek serta Jawa Barat dengan garansi penggantian 100% keping baru di lokasi proyek.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T16:00:12.000000Z', NULL, NULL, '2026-08-31T15:52:43.000000Z', '2026-08-31T16:11:42.000000Z');
