REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('320', 'ventilasi-dinding-roster-anti-tampias-air', 'pillar', 'ventilasi dinding roster anti tampias air', '[\"jual ventilasi dinding roster anti tampias air\",\"harga ventilasi dinding roster anti tampias air per keping\",\"supplier ventilasi dinding roster anti tampias air pabrik plered\",\"distributor ventilasi dinding roster anti tampias air jabodetabek\",\"ventilasi ventilasi dinding roster anti tampias air rumah minimalis\",\"kisi kisi ventilasi dinding roster anti tampias air dinding modern\"]', 'bofu', 'umum', 'residensial', NULL, NULL, NULL, 'Ventilasi Dinding Roster Anti Tampias Air — Standar Kualitas IndoRoster | Pabrik IndoRoster', 'Pusat produsen ventilasi dinding roster anti tampias air kualitas cetak padat presisi plat baja siku 90°. Bahan pasir abu batu murni, tahan lumut & garansi ama', NULL, NULL, NULL, NULL, '', 'Ventilasi Dinding Roster Anti Tampias Air — Standar Kualitas IndoRoster', 'Menghadapi musim hujan tropis dengan curah air tinggi dan angin kencang, pemasangan ventilasi dinding sering kali menimbulkan kekhawatiran air hujan menciprat masuk tampias membasahi interior. Produk ventilasi dinding roster anti tampias air dari IndoRoster dirancang dengan kemiringan sirip jalusi aerodinamis presisi yang membelokkan aliran butiran air hujan ke arah luar dinding secara alami, sembari tetap membiarkan udara segar mengalir lancar 24 jam tanpa henti ke dalam area dapur, tempat cuci jemur, maupun void tangga rumah Anda.', 'Teknik cetak tumbuk padat plat baja siku 90° presisi, menghemat adukan semen perekat tukang hingga 30% dan menghasilkan dinding yang tegak lurus sempurna.', 'Dipercaya oleh ribuan pemilik rumah tinggal, kontraktor tender, dan arsitek di Jabodetabek serta Jawa Barat dengan garansi penggantian 100% keping baru di lokasi proyek.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T16:00:12.000000Z', NULL, NULL, '2026-08-31T15:53:35.000000Z', '2026-08-31T16:11:42.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5105', '320', 'problem', 'Kendala Cipratan Hujan & Ruangan Becek Akibat Lubang Angin Biasa', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Banyak lubang angin konvensional tidak memiliki geometri pembelok air hujan, sehingga memicu berbagai masalah rumah tangga:</p>
                    <div class=\"space-y-3.5 not-prose\">
                        <div class=\"p-4 rounded-2xl bg-rose-50/60 dark:bg-rose-950/30 border border-rose-200/60 dark:border-rose-900/40\">
                            <strong class=\"text-sm font-bold text-slate-900 dark:text-white block\">Lantai Becek & Dinding Lembab Berjamur</strong>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-0.5\">Percikan air hujan yang menembus celah ventilasi membuat lantai licin berbahaya dan menyebabkan dinding plesteran mengelupas akibat kelembaban tinggi.</p>
                        </div>
                    </div>', '1', '1', NULL, NULL, '2026-08-31T16:00:13.000000Z', '2026-08-31T16:00:13.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5106', '320', 'solution', 'Inovasi Sirip Nako Aerodinamis: Bebas Tampias & Sirkulasi Maksimal', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Setiap keping loster nako IndoRoster dicetak menggunakan matras plat baja dengan kemiringan sudut presisi yang mengalirkan air hujan langsung ke bawah permukaan luar, menjaga area dalam rumah selalu kering dan bersih.</p>', '2', '1', NULL, NULL, '2026-08-31T16:00:13.000000Z', '2026-08-31T16:00:13.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5107', '320', 'specs', 'Rekomendasi Penempatan Loster Nako Anti Tampias', '<div class=\"grid grid-cols-1 md:grid-cols-3 gap-6 not-prose\">
                        <div class=\"p-5 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
