REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5274', '376', 'solution', 'Presisi Geometris Matras Plat Baja Siku 90 Derajat', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">IndoRoster menjamin keseragaman dimensi dan ketebalan antar keping dengan toleransi mikro, memungkinkan aplikasi nat semen tipis (*thin-bed mortar*) yang rapi dan elegan.</p>', '2', '1', NULL, NULL, '2026-08-31T16:00:13.000000Z', '2026-08-31T16:00:13.000000Z');
