REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('378', 'breeze-block-white-smooth-finish-vol-3', 'project', 'breeze block white smooth finish', '[\"jual breeze block white smooth finish\",\"harga breeze block white smooth finish per keping\",\"supplier breeze block white smooth finish pabrik plered\",\"distributor breeze block white smooth finish jabodetabek\",\"ventilasi breeze block white smooth finish rumah minimalis\",\"kisi kisi breeze block white smooth finish dinding modern\"]', 'bofu', 'arsitek', 'residensial', NULL, NULL, NULL, 'Inspirasi Aplikasi Breeze Block White Smooth Finish untuk Proyek Bangunan Anda | Pabrik IndoRoster', 'Pusat produsen breeze block white smooth finish kualitas cetak padat presisi plat baja siku 90°. Bahan pasir abu batu murni, tahan lumut & garansi aman kirim p', NULL, NULL, NULL, NULL, '', 'Inspirasi Aplikasi Breeze Block White Smooth Finish untuk Proyek Bangunan Anda', 'Bagi kalangan studio arsitektur kontemporer dan desainer interior, konsep breeze block bukan sekadar lubang ventilasi, melainkan media eksplorasi bayangan shadow play, pencahayaan alami bergradasi, dan tekstur dinding arsitektural berskala tinggi. Koleksi breeze block white smooth finish dari IndoRoster diproduksi dengan matras plat baja presisi tinggi, menghasilkan tepian siku 90 derajat yang tajam, permukaan padat bebas retak rambut, dan fleksibilitas pola susun staggered maupun grid aligned yang spektakuler.', 'Teknik cetak tumbuk padat plat baja siku 90° presisi, menghemat adukan semen perekat tukang hingga 30% dan menghasilkan dinding yang tegak lurus sempurna.', 'Dipercaya oleh ribuan pemilik rumah tinggal, kontraktor tender, dan arsitek di Jabodetabek serta Jawa Barat dengan garansi penggantian 100% keping baru di lokasi proyek.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T16:00:12.000000Z', NULL, NULL, '2026-08-31T15:54:30.000000Z', '2026-08-31T16:11:42.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5279', '378', 'problem', 'Tantangan Desain Fasad Arsitektural: Sudut Melengkung & Nat Berantakan', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Material cetakan manual yang tidak presisi sering merusak visi estetika gambar kerja arsitek di lapangan.</p>', '1', '1', NULL, NULL, '2026-08-31T16:00:13.000000Z', '2026-08-31T16:00:13.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5280', '378', 'solution', 'Presisi Geometris Matras Plat Baja Siku 90 Derajat', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">IndoRoster menjamin keseragaman dimensi dan ketebalan antar keping dengan toleransi mikro, memungkinkan aplikasi nat semen tipis (*thin-bed mortar*) yang rapi dan elegan.</p>', '2', '1', NULL, NULL, '2026-08-31T16:00:13.000000Z', '2026-08-31T16:00:13.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5281', '378', 'specs', 'Kelebihan Teknis untuk Desain Arsitektur Modern', '<div class=\"grid grid-cols-1 md:grid-cols-3 gap-6 not-prose\">
