REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5301', '385', 'solution', 'Presisi Geometris Matras Plat Baja Siku 90 Derajat', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">IndoRoster menjamin keseragaman dimensi dan ketebalan antar keping dengan toleransi mikro, memungkinkan aplikasi nat semen tipis (*thin-bed mortar*) yang rapi dan elegan.</p>', '2', '1', NULL, NULL, '2026-08-31T16:00:13.000000Z', '2026-08-31T16:00:13.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5302', '385', 'specs', 'Kelebihan Teknis untuk Desain Arsitektur Modern', '<div class=\"grid grid-cols-1 md:grid-cols-3 gap-6 not-prose\">
                        <div class=\"p-5 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                            <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">Shadow Play Spektakuler</h4>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300\">Membentuk pola bayangan sinar matahari yang dinamis pada lantai interior dan fasad.</p>
                        </div>
                        <div class=\"p-5 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                            <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">Passive Cooling Efisien</h4>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300\">Meredam panas radiasi matahari hingga 40% dan mengalirkan sirkulasi angin segar.</p>
                        </div>
                        <div class=\"p-5 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                            <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">Integrasi Tulangan Besi</h4>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300\">Modul keping siap dipasang tulangan besi horizontal dan vertikal untuk dinding tinggi.</p>
                        </div>
                    </div>', '3', '1', NULL, NULL, '2026-08-31T16:00:13.000000Z', '2026-08-31T16:00:13.000000Z');
REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('386', 'kisi-kisi-loster-partisi-ruang-cafe-vol-3', 'usecase', 'kisi kisi loster partisi ruang cafe', '[\"jual kisi kisi loster partisi ruang cafe\",\"harga kisi kisi loster partisi ruang cafe per keping\",\"supplier kisi kisi loster partisi ruang cafe pabrik plered\",\"distributor kisi kisi loster partisi ruang cafe jabodetabek\",\"ventilasi kisi kisi loster partisi ruang cafe rumah minimalis\",\"kisi kisi kisi kisi loster partisi ruang cafe dinding modern\"]', 'bofu', 'umum', 'residensial', NULL, NULL, NULL, 'Inspirasi Aplikasi Kisi Kisi Loster Partisi Ruang Cafe untuk Proyek Bangunan Anda | Pabrik IndoRoster', 'Pusat produsen kisi kisi loster partisi ruang cafe kualitas cetak padat presisi plat baja siku 90°. Bahan pasir abu batu murni, tahan lumut & garansi aman kiri', NULL, NULL, NULL, NULL, '', 'Inspirasi Aplikasi Kisi Kisi Loster Partisi Ruang Cafe untuk Proyek Bangunan Anda', 'Mewujudkan bangunan tropis yang sejuk, estetik, dan berdaya tahan puluhan tahun membutuhkan material dinding ventilasi berkualitas tinggi. Dalam pembahasan mengenai kisi kisi loster partisi ruang cafe, IndoRoster hadir sebagai produsen terpercaya dari sentra kerajinan Plered Purwakarta. Kami memadukan formula agregat pasir abu batu murni pilihan dengan teknik cetak tumbuk semi-kering bertenaga tinggi, menghasilkan keping loster berbobot padat 3.8–4.2 kg, berpori rapat anti-lumut, serta bersudut siku 90 derajat yang presisi untuk kesempurnaan dinding rumah Anda.', 'Teknik cetak tumbuk padat plat baja siku 90° presisi, menghemat adukan semen perekat tukang hingga 30% dan menghasilkan dinding yang tegak lurus sempurna.', 'Dipercaya oleh ribuan pemilik rumah tinggal, kontraktor tender, dan arsitek di Jabodetabek serta Jawa Barat dengan garansi penggantian 100% keping baru di lokasi proyek.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T16:00:12.000000Z', NULL, NULL, '2026-08-31T15:55:08.000000Z', '2026-08-31T16:00:13.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5303', '386', 'problem', 'Tantangan Dinding Rumah Tropis: Hawa Panas & Loster Mudah Gompal', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Banyak hunian di perkotaan mengalami sirkulasi udara yang buruk akibat penggunaan dinding tertutup masif, sementara pemilihan loster cor basah murahan sering kali menimbulkan masalah sudut miring dan lumut kerak hitam.</p>', '1', '1', NULL, NULL, '2026-08-31T16:00:13.000000Z', '2026-08-31T16:00:13.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5304', '386', 'solution', 'Standar Manufaktur Matras Plat Baja Presisi IndoRoster', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Keping loster IndoRoster memiliki kepadatan partikel tinggi yang tahan benturan, minim resapan air hujan, dan memiliki toleransi dimensi yang sangat rapi untuk memudahkan kerja tukang serta menghemat adukan semen perekat.</p>', '2', '1', NULL, NULL, '2026-08-31T16:00:13.000000Z', '2026-08-31T16:00:13.000000Z');
