REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5399', '418', 'problem', 'Risiko Kesalahan Estimasi Volume Roster di Lapangan', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Menghitung jumlah roster tanpa memperhitungkan modul dimensi dan margin pemotongan sering berakibat fatal:</p>
                    <div class=\"space-y-3.5 not-prose\">
                        <div class=\"p-4 rounded-2xl bg-rose-50/60 dark:bg-rose-950/30 border border-rose-200/60 dark:border-rose-900/40\">
                            <strong class=\"text-sm font-bold text-slate-900 dark:text-white block\">Pekerjaan Terhenti Akibat Kurang Barang</strong>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-0.5\">Membeli pas-pasan tanpa cadangan potongan nat sudut tukang membuat pekerjaan tukang tertunda dan menambah biaya ongkos kirim susulan.</p>
                        </div>
                    </div>', '1', '1', NULL, NULL, '2026-08-31T16:00:13.000000Z', '2026-08-31T16:00:13.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5400', '418', 'solution', 'Rumus Standar Praktis: Luas Bidang (m²) × 25 pcs + Cadangan 3–5%', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Cukup hitung panjang dinding dikalikan tinggi dinding dalam satuan meter, lalu kalikan 25 keping. Tambahkan margin aman 3–5% untuk potongan sudut nat kolom tukang.</p>', '2', '1', NULL, NULL, '2026-08-31T16:00:13.000000Z', '2026-08-31T16:00:13.000000Z');
