REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('436', 'perhitungan-tonase-roster-untuk-ekspedisi-fuso-vol-2', 'guide', 'perhitungan tonase roster untuk ekspedisi fuso', '[\"jual perhitungan tonase roster untuk ekspedisi fuso\",\"harga perhitungan tonase roster untuk ekspedisi fuso per keping\",\"supplier perhitungan tonase roster untuk ekspedisi fuso pabrik plered\",\"distributor perhitungan tonase roster untuk ekspedisi fuso jabodetabek\",\"ventilasi perhitungan tonase roster untuk ekspedisi fuso rumah minimalis\",\"kisi kisi perhitungan tonase roster untuk ekspedisi fuso dinding modern\"]', 'bofu', 'umum', 'residensial', NULL, NULL, NULL, 'Panduan & Harga Perhitungan Tonase Roster Untuk Ekspedisi Fuso Langsung dari Pabrik | Pabrik IndoRoster', 'Pusat produsen perhitungan tonase roster untuk ekspedisi fuso kualitas cetak padat presisi plat baja siku 90°. Bahan pasir abu batu murni, tahan lumut & garans', NULL, NULL, NULL, NULL, '', 'Panduan & Harga Perhitungan Tonase Roster Untuk Ekspedisi Fuso Langsung dari Pabrik', 'Perencanaan anggaran belanja material dinding yang akurat adalah kunci sukses proyek konstruksi tanpa risiko pembengkakan biaya over-budget maupun kekurangan material di tengah jalan. Pembahasan mengenai perhitungan tonase roster untuk ekspedisi fuso membantu Anda menghitung kebutuhan keping secara presisi berdasarkan standar modular IndoRoster: dimensi 20 × 20 × 10 cm dengan rasio kebutuhan tepat 25 pcs per 1 meter persegi luas dinding.', 'Teknik cetak tumbuk padat plat baja siku 90° presisi, menghemat adukan semen perekat tukang hingga 30% dan menghasilkan dinding yang tegak lurus sempurna.', 'Dipercaya oleh ribuan pemilik rumah tinggal, kontraktor tender, dan arsitek di Jabodetabek serta Jawa Barat dengan garansi penggantian 100% keping baru di lokasi proyek.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T16:00:12.000000Z', NULL, NULL, '2026-08-31T15:55:08.000000Z', '2026-08-31T16:11:42.000000Z');
