REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('452', 'cara-menghitung-kebutuhan-roster-dinding-pagar-vol-3', 'guide', 'cara menghitung kebutuhan roster dinding pagar', '[\"jual cara menghitung kebutuhan roster dinding pagar\",\"harga cara menghitung kebutuhan roster dinding pagar per keping\",\"supplier cara menghitung kebutuhan roster dinding pagar pabrik plered\",\"distributor cara menghitung kebutuhan roster dinding pagar jabodetabek\",\"ventilasi cara menghitung kebutuhan roster dinding pagar rumah minimalis\",\"kisi kisi cara menghitung kebutuhan roster dinding pagar dinding modern\"]', 'bofu', 'umum', 'residensial', NULL, NULL, NULL, 'Inspirasi Aplikasi Cara Menghitung Kebutuhan Roster Dinding Pagar untuk Proyek Bangunan Anda | Pabrik IndoRoster', 'Pusat produsen cara menghitung kebutuhan roster dinding pagar kualitas cetak padat presisi plat baja siku 90°. Bahan pasir abu batu murni, tahan lumut & garans', NULL, NULL, NULL, NULL, '', 'Inspirasi Aplikasi Cara Menghitung Kebutuhan Roster Dinding Pagar untuk Proyek Bangunan Anda', 'Perhitungan volume dan estimasi biaya material secara akurat merupakan langkah awal paling krusial dalam menyusun Rencana Anggaran Biaya (RAB) bangunan. Pembahasan mengenai cara menghitung kebutuhan roster dinding pagar memberikan panduan praktis berdasarkan standar dimensi modular IndoRoster: ukuran 20 × 20 × 10 cm dengan kebutuhan tepat 25 keping per 1 meter persegi luas bidang dinding pasangan.', 'Teknik cetak tumbuk padat plat baja siku 90° presisi, menghemat adukan semen perekat tukang hingga 30% dan menghasilkan dinding yang tegak lurus sempurna.', 'Dipercaya oleh ribuan pemilik rumah tinggal, kontraktor tender, dan arsitek di Jabodetabek serta Jawa Barat dengan garansi penggantian 100% keping baru di lokasi proyek.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T16:30:16.000000Z', NULL, NULL, '2026-08-31T16:30:16.000000Z', '2026-08-31T16:30:16.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5501', '452', 'problem', 'Risiko Kesalahan Perhitungan Volume Roster di Lapangan', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Salah menghitung kebutuhan loster sering berakibat fatal pada kelancaran pekerjaan tukang:</p>
                    <div class=\"space-y-3.5 not-prose\">
                        <div class=\"p-4 rounded-2xl bg-rose-50/60 dark:bg-rose-950/30 border border-rose-200/60 dark:border-rose-900/40\">
                            <strong class=\"text-sm font-bold text-slate-900 dark:text-white block\">Pekerjaan Tertunda Akibat Kurang Barang</strong>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-0.5\">Membeli tanpa memperhitungkan potongan sudut tukang membuat proyek terhenti di tengah jalan dan menambah ongkos kirim susulan.</p>
                        </div>
                    </div>', '1', '1', NULL, NULL, '2026-08-31T16:30:16.000000Z', '2026-08-31T16:30:16.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5502', '452', 'solution', 'Rumus Praktis: Panjang × Tinggi (m²) × 25 pcs + Cadangan 3–5%', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Cukup hitung luas total bidang dinding dalam meter persegi, kalikan dengan 25 pcs, lalu tambahkan margin aman 3–5% untuk pemotongan nat sudut kolom tukang.</p>', '2', '1', NULL, NULL, '2026-08-31T16:30:16.000000Z', '2026-08-31T16:30:16.000000Z');
