REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('529', 'roster-dolomit-putih-untuk-fasad-scandinavian-vol-2', 'pillar', 'roster dolomit putih untuk fasad scandinavian', '[\"jual roster dolomit putih untuk fasad scandinavian\",\"harga roster dolomit putih untuk fasad scandinavian per keping\",\"supplier roster dolomit putih untuk fasad scandinavian pabrik plered\",\"distributor roster dolomit putih untuk fasad scandinavian jabodetabek\",\"ventilasi roster dolomit putih untuk fasad scandinavian rumah minimalis\",\"kisi kisi roster dolomit putih untuk fasad scandinavian dinding modern\"]', 'bofu', 'umum', 'residensial', NULL, NULL, NULL, 'Panduan & Harga Roster Dolomit Putih Untuk Fasad Scandinavian Langsung dari Pabrik | Pabrik IndoRoster', 'Pusat produsen roster dolomit putih untuk fasad scandinavian kualitas cetak padat presisi plat baja siku 90°. Bahan pasir abu batu murni, tahan lumut & garansi', NULL, NULL, NULL, NULL, '', 'Panduan & Harga Roster Dolomit Putih Untuk Fasad Scandinavian Langsung dari Pabrik', 'Bagi Anda yang menginginkan tampilan dinding bernuansa Scandinavian, Japandi, atau tropis modern yang bersih dan terang, roster dolomit putih untuk fasad scandinavian dari IndoRoster diproduksi dari 100% batuan dolomit putih super alami. Kemurnian warna putih mineral dolomit memberikan kilau putih alami luar dalam yang tidak mudah kusam, tahan air, dan secara alami bebas dari lumut hitam.', 'Teknik cetak tumbuk padat plat baja siku 90° presisi, menghemat adukan semen perekat tukang hingga 30% dan menghasilkan dinding yang tegak lurus sempurna.', 'Dipercaya oleh ribuan pemilik rumah tinggal, kontraktor tender, dan arsitek di Jabodetabek serta Jawa Barat dengan garansi penggantian 100% keping baru di lokasi proyek.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T16:30:16.000000Z', NULL, NULL, '2026-08-31T16:30:16.000000Z', '2026-08-31T16:30:16.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5732', '529', 'problem', 'Masalah Cat Putih Belang & Dinding Cepat Kusam', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Roster abu-abu yang dicat putih permukaannya sering kali mengelupas dan belang saat terpapar hujan deras dan terik matahari.</p>', '1', '1', NULL, NULL, '2026-08-31T16:30:16.000000Z', '2026-08-31T16:30:16.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5733', '529', 'solution', 'Putih Alami Murni Batuan Dolomit Padat', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Tanpa cat semprot sintetis, mineral dolomit memiliki daya serap air yang sangat minim sehingga spora jamur dan lumut tidak dapat tumbuh merusak estetika dinding.</p>', '2', '1', NULL, NULL, '2026-08-31T16:30:16.000000Z', '2026-08-31T16:30:16.000000Z');
