REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5748', '534', 'solution', 'Putih Alami Murni Batuan Dolomit Padat', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Tanpa cat semprot sintetis, mineral dolomit memiliki daya serap air yang sangat minim sehingga spora jamur dan lumut tidak dapat tumbuh merusak estetika dinding.</p>', '2', '1', NULL, NULL, '2026-08-31T16:30:16.000000Z', '2026-08-31T16:30:16.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5749', '534', 'specs', 'Keunggulan Bahan Dolomit Super', '<div class=\"grid grid-cols-1 md:grid-cols-3 gap-6 not-prose\">
