REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5833', '562', 'specs', 'Aplikasi Loster Terakota Merah Bata', '<div class=\"grid grid-cols-1 md:grid-cols-3 gap-6 not-prose\">
