REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('613', 'roster-motif-nako-jalusi-anti-tampias-vol-2', 'pillar', 'roster motif nako jalusi anti tampias', '[\"jual roster motif nako jalusi anti tampias\",\"harga roster motif nako jalusi anti tampias per keping\",\"supplier roster motif nako jalusi anti tampias pabrik plered\",\"distributor roster motif nako jalusi anti tampias jabodetabek\",\"ventilasi roster motif nako jalusi anti tampias rumah minimalis\",\"kisi kisi roster motif nako jalusi anti tampias dinding modern\"]', 'bofu', 'umum', 'residensial', NULL, NULL, NULL, 'Panduan & Harga Roster Motif Nako Jalusi Anti Tampias Langsung dari Pabrik | Pabrik IndoRoster', 'Pusat produsen roster motif nako jalusi anti tampias kualitas cetak padat presisi plat baja siku 90°. Bahan pasir abu batu murni, tahan lumut & garansi aman ki', NULL, NULL, NULL, NULL, '', 'Panduan & Harga Roster Motif Nako Jalusi Anti Tampias Langsung dari Pabrik', 'Menghadapi curah hujan tropis yang tinggi, pemilihan ventilasi dinding harus mampu membuang uap panas tanpa membiarkan air hujan menciprat masuk ke dalam rumah. Pembahasan roster motif nako jalusi anti tampias dari IndoRoster menghadirkan solusi kisi-kisi nako dengan sudut kemiringan presisi yang membelokkan butiran air hujan ke arah luar secara alami, menjaga lantai dan perabotan interior Anda tetap kering sempurna.', 'Teknik cetak tumbuk padat plat baja siku 90° presisi, menghemat adukan semen perekat tukang hingga 30% dan menghasilkan dinding yang tegak lurus sempurna.', 'Dipercaya oleh ribuan pemilik rumah tinggal, kontraktor tender, dan arsitek di Jabodetabek serta Jawa Barat dengan garansi penggantian 100% keping baru di lokasi proyek.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T16:30:16.000000Z', NULL, NULL, '2026-08-31T16:30:16.000000Z', '2026-08-31T16:30:16.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5984', '613', 'problem', 'Risiko Rembesan Air & Dinding Rusak Akibat Tampias Hujan', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Lubang angin tanpa sudut kemiringan sirip yang presisi sering kali menjadi jalur masuk air hujan saat diterpa angin kencang:</p>
                    <div class=\"space-y-3.5 not-prose\">
                        <div class=\"p-4 rounded-2xl bg-rose-50/60 dark:bg-rose-950/30 border border-rose-200/60 dark:border-rose-900/40\">
                            <strong class=\"text-sm font-bold text-slate-900 dark:text-white block\">Lantai Becek & Jamur Dinding</strong>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-0.5\">Percikan air hujan yang masuk merusak cat interior, membasahi area cuci jemur, dan menimbulkan kerak lumut pada plesteran.</p>
                        </div>
                    </div>', '1', '1', NULL, NULL, '2026-08-31T16:30:16.000000Z', '2026-08-31T16:30:16.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5985', '613', 'solution', 'Geometri Sirip Nako Presisi Pembelok Air Hujan', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Matras plat baja IndoRoster mencetak sirip jalusi dengan kemiringan tajam yang mengalirkan air hujan langsung ke bawah permukaan luar tanpa menghambat hembusan angin segar.</p>', '2', '1', NULL, NULL, '2026-08-31T16:30:16.000000Z', '2026-08-31T16:30:16.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('5986', '613', 'specs', 'Area Aplikasi Loster Anti Tampias', '<div class=\"grid grid-cols-1 md:grid-cols-3 gap-6 not-prose\">
                        <div class=\"p-5 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                            <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">Area Dapur & Cuci Jemur</h4>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300\">Membuang uap masakan tanpa khawatir pakaian jemuran basah terciprat hujan.</p>
                        </div>
                        <div class=\"p-5 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                            <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">Void Tangga & Bordes</h4>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300\">Pencahayaan alami dan sirkulasi vertikal bebas dari cipratan air ke anak tangga.</p>
                        </div>
                        <div class=\"p-5 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                            <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">Dinding Samping Lorong</h4>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300\">Mengalirkan angin sejuk antar ruangan dengan perlindungan cuaca maksimal.</p>
                        </div>
                    </div>', '3', '1', NULL, NULL, '2026-08-31T16:30:16.000000Z', '2026-08-31T16:30:16.000000Z');
