REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('6103', '652', 'specs', 'Spesifikasi Standar Produk IndoRoster', '<div class=\"grid grid-cols-1 md:grid-cols-3 gap-6 not-prose\">
                        <div class=\"p-5 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                            <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">Dimensi Modular 20x20x10 cm</h4>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300\">Kebutuhan presisi tepat 25 pcs per 1 m² luas dinding pasangan.</p>
                        </div>
                        <div class=\"p-5 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                            <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">Bobot Padat 3.8–4.2 kg</h4>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300\">Kepadatan cetak tumbuk semi-kering yang kokoh dan tahan guncangan.</p>
                        </div>
                        <div class=\"p-5 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                            <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">Garansi Bebas Pecah 100%</h4>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300\">Pengiriman langsung armada pabrik dengan penggantian baru di tempat.</p>
                        </div>
                    </div>', '3', '1', NULL, NULL, '2026-08-31T16:30:17.000000Z', '2026-08-31T16:30:17.000000Z');
REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('653', 'roster-motif-terowongan-kubus-ilusi-optik-vol-3', 'pillar', 'roster motif terowongan kubus ilusi optik', '[\"jual roster motif terowongan kubus ilusi optik\",\"harga roster motif terowongan kubus ilusi optik per keping\",\"supplier roster motif terowongan kubus ilusi optik pabrik plered\",\"distributor roster motif terowongan kubus ilusi optik jabodetabek\",\"ventilasi roster motif terowongan kubus ilusi optik rumah minimalis\",\"kisi kisi roster motif terowongan kubus ilusi optik dinding modern\"]', 'bofu', 'umum', 'residensial', NULL, NULL, NULL, 'Inspirasi Aplikasi Roster Motif Terowongan Kubus Ilusi Optik untuk Proyek Bangunan Anda | Pabrik IndoRoster', 'Pusat produsen roster motif terowongan kubus ilusi optik kualitas cetak padat presisi plat baja siku 90°. Bahan pasir abu batu murni, tahan lumut & garansi ama', NULL, NULL, NULL, NULL, '', 'Inspirasi Aplikasi Roster Motif Terowongan Kubus Ilusi Optik untuk Proyek Bangunan Anda', 'Mewujudkan bangunan tropis yang sejuk, estetik, dan berdaya tahan puluhan tahun membutuhkan material dinding ventilasi berkualitas tinggi. Dalam pembahasan roster motif terowongan kubus ilusi optik, IndoRoster hadir sebagai produsen terpercaya dari sentra kerajinan Plered Purwakarta. Kami memadukan formula agregat pasir abu batu murni pilihan dengan teknik cetak tumbuk semi-kering bertenaga tinggi, menghasilkan keping loster berbobot padat 3.8–4.2 kg, berpori rapat anti-lumut, serta bersudut siku 90 derajat yang presisi untuk kesempurnaan dinding rumah Anda.', 'Teknik cetak tumbuk padat plat baja siku 90° presisi, menghemat adukan semen perekat tukang hingga 30% dan menghasilkan dinding yang tegak lurus sempurna.', 'Dipercaya oleh ribuan pemilik rumah tinggal, kontraktor tender, dan arsitek di Jabodetabek serta Jawa Barat dengan garansi penggantian 100% keping baru di lokasi proyek.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T16:30:16.000000Z', NULL, NULL, '2026-08-31T16:30:17.000000Z', '2026-08-31T16:30:17.000000Z');
