REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('6282', '712', 'solution', 'Presisi Sudut Siku 90 Derajat Plat Baja IndoRoster', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Dengan cetakan plat baja tebal, setiap keping loster memiliki ukuran modular 20x20x10 cm yang sangat presisi, memungkinkan ketebalan nat spesi tipis hanya 2–3 mm.</p>', '2', '1', NULL, NULL, '2026-08-31T16:35:25.000000Z', '2026-08-31T16:35:25.000000Z');
