REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('736', 'cara-mengatasi-sudut-roster-yang-miring-tidak-siku-90-derajat-vol-3', 'guide', 'cara mengatasi sudut roster yang miring tidak siku 90 derajat', '[\"jual cara mengatasi sudut roster yang miring tidak siku 90 derajat\",\"harga cara mengatasi sudut roster yang miring tidak siku 90 derajat per keping\",\"supplier cara mengatasi sudut roster yang miring tidak siku 90 derajat pabrik plered\",\"distributor cara mengatasi sudut roster yang miring tidak siku 90 derajat jabodetabek\",\"ventilasi cara mengatasi sudut roster yang miring tidak siku 90 derajat rumah minimalis\",\"kisi kisi cara mengatasi sudut roster yang miring tidak siku 90 derajat dinding modern\"]', 'bofu', 'tukang', 'residensial', NULL, NULL, NULL, 'Inspirasi Aplikasi Cara Mengatasi Sudut Roster Yang Miring Tidak Siku 90 Derajat untuk Proyek Bangunan Anda | Pabrik IndoRoster', 'Pusat produsen cara mengatasi sudut roster yang miring tidak siku 90 derajat kualitas cetak padat presisi plat baja siku 90°. Bahan pasir abu batu murni, tahan', NULL, NULL, NULL, NULL, '', 'Inspirasi Aplikasi Cara Mengatasi Sudut Roster Yang Miring Tidak Siku 90 Derajat untuk Proyek Bangunan Anda', 'Ketahanan struktural dan kecepatan kerja tukang di lapangan sangat ditentukan oleh kualitas presisi material keping loster. Dalam topik cara mengatasi sudut roster yang miring tidak siku 90 derajat, IndoRoster menerapkan standar manufaktur matras plat baja dengan toleransi mikro-milimeter, memastikan setiap sudut siku tepat 90 derajat sehingga pemasangan dinding tegak lurus sempurna dan menghemat spesi semen mortar hingga 30%.', 'Teknik cetak tumbuk padat plat baja siku 90° presisi, menghemat adukan semen perekat tukang hingga 30% dan menghasilkan dinding yang tegak lurus sempurna.', 'Dipercaya oleh ribuan pemilik rumah tinggal, kontraktor tender, dan arsitek di Jabodetabek serta Jawa Barat dengan garansi penggantian 100% keping baru di lokasi proyek.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T16:35:25.000000Z', NULL, NULL, '2026-08-31T16:35:25.000000Z', '2026-08-31T16:35:25.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('6353', '736', 'problem', 'Kendala Loster Miring & Boros Spesi Semen Adukan', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Loster cor basah cetakan kayu sering kali melengkung, tidak siku, dan memiliki selisih ukuran hingga 5 mm yang memperlambat pekerjaan tukang.</p>', '1', '1', NULL, NULL, '2026-08-31T16:35:25.000000Z', '2026-08-31T16:35:25.000000Z');
