REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('746', 'cara-merawat-roster-putih-dolomit-agar-tetap-bersih-tidak-kuning-vol-3', 'pillar', 'cara merawat roster putih dolomit agar tetap bersih tidak kuning', '[\"jual cara merawat roster putih dolomit agar tetap bersih tidak kuning\",\"harga cara merawat roster putih dolomit agar tetap bersih tidak kuning per keping\",\"supplier cara merawat roster putih dolomit agar tetap bersih tidak kuning pabrik plered\",\"distributor cara merawat roster putih dolomit agar tetap bersih tidak kuning jabodetabek\",\"ventilasi cara merawat roster putih dolomit agar tetap bersih tidak kuning rumah minimalis\",\"kisi kisi cara merawat roster putih dolomit agar tetap bersih tidak kuning dinding modern\"]', 'bofu', 'umum', 'residensial', NULL, NULL, NULL, 'Inspirasi Aplikasi Cara Merawat Roster Putih Dolomit Agar Tetap Bersih Tidak Kuning untuk Proyek Bangunan Anda | Pabrik IndoRoster', 'Pusat produsen cara merawat roster putih dolomit agar tetap bersih tidak kuning kualitas cetak padat presisi plat baja siku 90°. Bahan pasir abu batu murni, ta', NULL, NULL, NULL, NULL, '', 'Inspirasi Aplikasi Cara Merawat Roster Putih Dolomit Agar Tetap Bersih Tidak Kuning untuk Proyek Bangunan Anda', 'Mewujudkan bangunan tropis yang sejuk, estetik, dan berdaya tahan puluhan tahun membutuhkan material dinding ventilasi berkualitas tinggi. Dalam pembahasan cara merawat roster putih dolomit agar tetap bersih tidak kuning, IndoRoster hadir sebagai produsen terpercaya dari sentra kerajinan Plered Purwakarta. Kami memadukan formula agregat pasir abu batu murni pilihan dengan teknik cetak tumbuk semi-kering bertenaga tinggi, menghasilkan keping loster berbobot padat 3.8–4.2 kg, berpori rapat anti-lumut, serta bersudut siku 90 derajat yang presisi untuk kesempurnaan dinding rumah Anda.', 'Teknik cetak tumbuk padat plat baja siku 90° presisi, menghemat adukan semen perekat tukang hingga 30% dan menghasilkan dinding yang tegak lurus sempurna.', 'Dipercaya oleh ribuan pemilik rumah tinggal, kontraktor tender, dan arsitek di Jabodetabek serta Jawa Barat dengan garansi penggantian 100% keping baru di lokasi proyek.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T16:35:25.000000Z', NULL, NULL, '2026-08-31T16:35:25.000000Z', '2026-08-31T16:35:25.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('6383', '746', 'problem', 'Tantangan Dinding Rumah Tropis: Hawa Panas & Loster Mudah Gompal', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Banyak hunian mengalami sirkulasi udara yang buruk akibat dinding tertutup masif, sementara pemilihan loster cor basah murahan sering kali menimbulkan masalah sudut miring dan lumut kerak hitam.</p>', '1', '1', NULL, NULL, '2026-08-31T16:35:25.000000Z', '2026-08-31T16:35:25.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('6384', '746', 'solution', 'Standar Manufaktur Matras Plat Baja Presisi IndoRoster', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Keping loster IndoRoster memiliki kepadatan partikel tinggi yang tahan benturan, minim resapan air hujan, dan memiliki toleransi dimensi yang sangat rapi untuk memudahkan kerja tukang serta menghemat adukan semen perekat.</p>', '2', '1', NULL, NULL, '2026-08-31T16:35:25.000000Z', '2026-08-31T16:35:25.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('6385', '746', 'specs', 'Spesifikasi Standar Produk IndoRoster', '<div class=\"grid grid-cols-1 md:grid-cols-3 gap-6 not-prose\">
                        <div class=\"p-5 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
