REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('7717', '1190', 'specs', 'Jangkauan Pengiriman & Logistik Cepat', '<div class=\"grid grid-cols-1 md:grid-cols-3 gap-6 not-prose\">
                        <div class=\"p-5 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                            <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">Pengiriman 1 Hari Kerja</h4>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300\">Rute harian via tol utama menjamin pesanan tiba tepat waktu di lokasi.</p>
                        </div>
                        <div class=\"p-5 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                            <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">Garansi Bebas Pecah 100%</h4>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300\">Setiap keping yang retak saat perjalanan langsung diganti baru di tempat.</p>
                        </div>
                        <div class=\"p-5 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
                            <h4 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">Fasilitas Gratis Ongkir</h4>
                            <p class=\"text-xs text-slate-600 dark:text-slate-300\">Subsidi bebas biaya pengiriman untuk pemesanan volume tertentu.</p>
                        </div>
                    </div>', '3', '1', NULL, NULL, '2026-08-31T17:10:02.000000Z', '2026-08-31T17:10:02.000000Z');
REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('1191', 'toko-roster-terdekat-jagakarsa-jaksel', 'location', 'toko roster terdekat jagakarsa jaksel', '[\"jual toko roster terdekat jagakarsa jaksel\",\"harga toko roster terdekat jagakarsa jaksel per keping\",\"supplier toko roster terdekat jagakarsa jaksel pabrik plered\",\"distributor toko roster terdekat jagakarsa jaksel pengiriman aman\",\"ventilasi toko roster terdekat jagakarsa jaksel rumah minimalis\",\"kisi kisi toko roster terdekat jagakarsa jaksel dinding modern\"]', 'bofu', 'pemilik_rumah', 'residensial', NULL, NULL, NULL, 'Pusat toko roster terdekat jagakarsa jaksel — Kirim Cepat Langsung Pabrik Plered (Gratis Ongkir Area Tertentu) | Pabrik IndoRoster', 'Pusat produsen toko roster terdekat jagakarsa jaksel kualitas cetak padat presisi plat baja siku 90°. Bahan pasir abu batu murni, tahan lumut & garansi aman ki', NULL, NULL, NULL, NULL, '', 'Pusat toko roster terdekat jagakarsa jaksel — Kirim Cepat Langsung Pabrik Plered (Gratis Ongkir Area Tertentu)', 'Mencari produsen dan pusat distributor toko roster terdekat jagakarsa jaksel kini semakin mudah, cepat, dan terjamin keasliannya langsung dari sentra Plered Purwakarta. Kami menghadirkan kemudahan pemesanan roster beton presisi matras plat baja siku 90 derajat dengan pengiriman 1 hari kerja sampai. Layanan kami didukung armada truk pabrik rutin dengan penawaran Promo GRATIS ONGKIR untuk volume pemesanan tertentu langsung ke gerbang proyek atau rumah Anda. Seluruh pengiriman dilindungi Garansi Bebas Pecah 100% dengan penggantian keping baru di tempat oleh sopir kami.', 'Teknik cetak tumbuk padat plat baja siku 90° presisi, menghemat adukan semen perekat tukang hingga 30% dan menghasilkan dinding yang tegak lurus sempurna.', 'Dipercaya oleh ribuan pemilik rumah tinggal, kontraktor tender, dan arsitek di Jabodetabek, Banten, Jawa Barat, dan kota-kota besar nasional dengan garansi penggantian 100% keping baru di lokasi.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T17:10:02.000000Z', NULL, NULL, '2026-08-31T17:10:02.000000Z', '2026-08-31T17:10:02.000000Z');
