REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('1194', 'supplier-roster-terdekat-pancoran-jaksel', 'location', 'supplier roster terdekat pancoran jaksel', '[\"jual supplier roster terdekat pancoran jaksel\",\"harga supplier roster terdekat pancoran jaksel per keping\",\"supplier supplier roster terdekat pancoran jaksel pabrik plered\",\"distributor supplier roster terdekat pancoran jaksel pengiriman aman\",\"ventilasi supplier roster terdekat pancoran jaksel rumah minimalis\",\"kisi kisi supplier roster terdekat pancoran jaksel dinding modern\"]', 'bofu', 'pemilik_rumah', 'residensial', NULL, NULL, NULL, 'Pusat supplier roster terdekat pancoran jaksel — Kirim Cepat Langsung Pabrik Plered (Gratis Ongkir Area Tertentu) | Pabrik IndoRoster', 'Pusat produsen supplier roster terdekat pancoran jaksel kualitas cetak padat presisi plat baja siku 90°. Bahan pasir abu batu murni, tahan lumut & garansi aman', NULL, NULL, NULL, NULL, '', 'Pusat supplier roster terdekat pancoran jaksel — Kirim Cepat Langsung Pabrik Plered (Gratis Ongkir Area Tertentu)', 'Mencari produsen dan pusat distributor supplier roster terdekat pancoran jaksel kini semakin mudah, cepat, dan terjamin keasliannya langsung dari sentra Plered Purwakarta. Kami menghadirkan kemudahan pemesanan roster beton presisi matras plat baja siku 90 derajat dengan pengiriman 1 hari kerja sampai. Layanan kami didukung armada truk pabrik rutin dengan penawaran Promo GRATIS ONGKIR untuk volume pemesanan tertentu langsung ke gerbang proyek atau rumah Anda. Seluruh pengiriman dilindungi Garansi Bebas Pecah 100% dengan penggantian keping baru di tempat oleh sopir kami.', 'Teknik cetak tumbuk padat plat baja siku 90° presisi, menghemat adukan semen perekat tukang hingga 30% dan menghasilkan dinding yang tegak lurus sempurna.', 'Dipercaya oleh ribuan pemilik rumah tinggal, kontraktor tender, dan arsitek di Jabodetabek, Banten, Jawa Barat, dan kota-kota besar nasional dengan garansi penggantian 100% keping baru di lokasi.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T17:10:02.000000Z', NULL, NULL, '2026-08-31T17:10:02.000000Z', '2026-08-31T17:10:02.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('7727', '1194', 'problem', 'Mahalnya Harga Toko Perantara & Risiko Keping Loster Pecah di Jalan', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Membeli loster di toko bangunan eceran sering kali dihadapkan pada harga yang melambung tinggi akibat margin perantara, stok terbatas, serta ketiadaan garansi ganti jika barang mengalami keretakan saat dibongkar.</p>', '1', '1', NULL, NULL, '2026-08-31T17:10:02.000000Z', '2026-08-31T17:10:02.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('7728', '1194', 'solution', 'Pesan Langsung Pabrik: Harga Tangan Pertama & Garansi 100% Ganti di Tempat', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">IndoRoster memotong rantai distribusi perantara, memberikan Anda harga pabrik tangan pertama yang jauh lebih hemat. Kepadatan cetak tumbuk semi-kering pasir abu batu murni menjamin setiap keping kokoh berbobot 3.8–4.2 kg dan tiba dalam kondisi sempurna.</p>', '2', '1', NULL, NULL, '2026-08-31T17:10:02.000000Z', '2026-08-31T17:10:02.000000Z');
