REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('1305', 'roster-beton-puri-kencana-mansion', 'pillar', 'roster beton puri kencana mansion', '[\"jual roster beton puri kencana mansion\",\"harga roster beton puri kencana mansion per keping\",\"supplier roster beton puri kencana mansion pabrik plered\",\"distributor roster beton puri kencana mansion pengiriman aman\",\"ventilasi roster beton puri kencana mansion rumah minimalis\",\"kisi kisi roster beton puri kencana mansion dinding modern\"]', 'bofu', 'umum', 'residensial', NULL, NULL, NULL, 'Inspirasi & Pengadaan Roster Beton untuk Puri Kencana Mansion — Presisi Siku 90° | Pabrik IndoRoster', 'Pusat produsen roster beton puri kencana mansion kualitas cetak padat presisi plat baja siku 90°. Bahan pasir abu batu murni, tahan lumut & garansi aman kirim ', NULL, NULL, NULL, NULL, '', 'Inspirasi & Pengadaan Roster Beton untuk Puri Kencana Mansion — Presisi Siku 90°', 'Menghadirkan kenyamanan hunian tropis yang sejuk, estetik, dan berdaya tahan puluhan tahun membutuhkan perencanaan dinding ventilasi yang matang. Dalam ulasan roster beton puri kencana mansion, IndoRoster hadir sebagai produsen terpercaya dari sentra kerajinan Plered Purwakarta. Kami memadukan formula agregat pasir abu batu murni pilihan dengan teknik cetak tumbuk semi-kering bertenaga tinggi, menghasilkan keping loster berbobot padat 3.8–4.2 kg, berpori rapat anti-lumut, serta bersudut siku 90 derajat yang presisi untuk kesempurnaan dinding rumah Anda.', 'Teknik cetak tumbuk padat plat baja siku 90° presisi, menghemat adukan semen perekat tukang hingga 30% dan menghasilkan dinding yang tegak lurus sempurna.', 'Dipercaya oleh ribuan pemilik rumah tinggal, kontraktor tender, dan arsitek di Jabodetabek, Banten, Jawa Barat, dan kota-kota besar nasional dengan garansi penggantian 100% keping baru di lokasi.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T17:10:02.000000Z', NULL, NULL, '2026-08-31T17:10:03.000000Z', '2026-08-31T17:10:03.000000Z');
