REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('8114', '1323', 'problem', 'Aturan Ketat Developer & Risiko Dinding Pagar Lembab Pengap', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Pagar masif tertutup sering dilarang oleh manajemen estate developer karena merusak keseragaman kawasan, sementara dinding tertutup membuat halaman depan dan carport mobil terasa gerah tanpa angin.</p>', '1', '1', NULL, NULL, '2026-08-31T17:10:03.000000Z', '2026-08-31T17:10:03.000000Z');
