REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('8117', '1324', 'problem', 'Mahalnya Harga Toko Perantara & Risiko Keping Loster Pecah di Jalan', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Membeli loster di toko bangunan eceran sering kali dihadapkan pada harga yang melambung tinggi akibat margin perantara, stok terbatas, serta ketiadaan garansi ganti jika barang mengalami keretakan saat dibongkar.</p>', '1', '1', NULL, NULL, '2026-08-31T17:10:03.000000Z', '2026-08-31T17:10:03.000000Z');
