REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('8344', '1398', 'specs', 'Spesifikasi Standar Produk IndoRoster', '<div class=\"grid grid-cols-1 md:grid-cols-3 gap-6 not-prose\">
                        <div class=\"p-5 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
