REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('1595', 'supplier-roster-beton-batam-centre', 'wholesale', 'supplier roster beton di batam centre', '[\"jual supplier roster beton di batam centre\",\"harga supplier roster beton di batam centre per keping\",\"supplier supplier roster beton di batam centre pabrik plered\",\"distributor supplier roster beton di batam centre pengiriman aman\",\"ventilasi supplier roster beton di batam centre rumah minimalis\",\"kisi kisi supplier roster beton di batam centre dinding modern\"]', 'bofu', 'kontraktor', 'residensial', NULL, NULL, NULL, 'Distributor & Pengadaan Roster Beton di Batam, Kepulauan Riau — Kirim Fuso Aman | Pabrik IndoRoster', 'Pusat produsen supplier roster beton di batam centre kualitas cetak padat presisi plat baja siku 90°. Bahan pasir abu batu murni, tahan lumut & garansi aman ki', NULL, NULL, NULL, NULL, '', 'Distributor & Pengadaan Roster Beton di Batam, Kepulauan Riau — Kirim Fuso Aman', 'Bagi Anda yang berlokasi di supplier roster beton di batam centre, pengadaan roster beton berkualitas tinggi kini dapat dipesan langsung dari sentra pabrik IndoRoster Plered Purwakarta dengan biaya jauh lebih hemat dibanding membeli di toko bangunan lokal perantara. Melalui jaringan armada ekspedisi truk Fuso dan penyeberangan kapal ferry yang terintegrasi, kami menjamin pengiriman dalam volume partai sedang hingga besar tiba dengan aman dan dilindungi Garansi Bebas Pecah 100%.', 'Teknik cetak tumbuk padat plat baja siku 90° presisi, menghemat adukan semen perekat tukang hingga 30% dan menghasilkan dinding yang tegak lurus sempurna.', 'Dipercaya oleh ribuan pemilik rumah tinggal, kontraktor tender, dan arsitek di Jabodetabek, Banten, Jawa Barat, dan kota-kota besar nasional dengan garansi penggantian 100% keping baru di lokasi.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T17:10:02.000000Z', NULL, NULL, '2026-08-31T17:10:04.000000Z', '2026-08-31T17:10:04.000000Z');
