REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('9041', '1631', 'problem', 'Tingginya Harga Roster di Luar Jawa & Keterbatasan Pilihan Motif Lokal', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Toko material di luar pulau sering kali mematok harga tinggi hingga Rp 25.000–Rp 35.000 per keping dengan stok motif yang sangat terbatas dan mutu cetak cor basah yang rapuh saat terkena cuaca ekstrem pesisir.</p>', '1', '1', NULL, NULL, '2026-08-31T17:10:04.000000Z', '2026-08-31T17:10:04.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('9042', '1631', 'solution', 'Pesan Langsung Volume Truk Pabrik Plered: Hemat Hingga Puluhan Juta', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Dengan memesan 1 muatan truk Colt Diesel (800–1.200 pcs) atau Fuso (2.500–4.000 pcs), total biaya per keping termasuk ongkos kirim jatuh jauh lebih murah. Kualitas cetak tumbuk semi-kering pasir abu batu murni menjamin keping tahan guncangan dan tidak berlumut.</p>', '2', '1', NULL, NULL, '2026-08-31T17:10:04.000000Z', '2026-08-31T17:10:04.000000Z');
