REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('1791', 'tempat-beli-breeze-block-sawangan-depok', 'location', 'tempat beli breeze block di sawangan', '[\"jual tempat beli breeze block di sawangan\",\"beli tempat beli breeze block di sawangan\",\"harga tempat beli breeze block di sawangan per keping\",\"supplier breeze block pabrik plered\",\"screen block minimalis modern\",\"breeze block putih dolomit\"]', 'bofu', 'pemilik_rumah', 'residensial', NULL, NULL, NULL, 'Tempat Beli Breeze Block Minimalis di Sawangan, Depok — Pabrik Plered (Gratis Ongkir) | Pabrik IndoRoster', 'Pusat jual & beli tempat beli breeze block di sawangan mutu cetak padat presisi plat baja siku 90°. Pasir abu batu murni & dolomit putih, garansi aman kirim pa', NULL, NULL, NULL, NULL, '', 'Tempat Beli Breeze Block Minimalis di Sawangan, Depok — Pabrik Plered (Gratis Ongkir)', 'Mencari pusat penjualan dan tempat pembelian tempat beli breeze block di sawangan kini hadir lebih dekat, mudah, dan terjamin keasliannya langsung dari sentra pengrajin Plered Purwakarta. Kami menyediakan koleksi lengkap breeze block minimalis modern berstandar presisi matras plat baja siku 90 derajat yang siap dikirim menggunakan armada truk pabrik langsung ke gerbang proyek atau rumah Anda di Jabodetabek, Banten, dan Jawa Barat dengan fasilitas Promo GRATIS ONGKIR dan perlindungan Garansi Bebas Pecah 100% di tempat.', 'Teknik cetak tumbuk padat plat baja siku 90° presisi, menghemat adukan semen perekat tukang hingga 30% dan menghasilkan dinding fasad yang tegak lurus sempurna.', 'Dipercaya oleh ribuan pemilik rumah tinggal, kontraktor tender, dan arsitek di Jabodetabek, Banten, dan Jawa Barat dengan garansi penggantian 100% keping baru di lokasi.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T17:25:26.000000Z', NULL, NULL, '2026-08-31T17:25:26.000000Z', '2026-08-31T17:25:26.000000Z');
