REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('1998', 'jual-breeze-block-putih-dolomit-kramat-jati-jaktim', 'location', 'jual breeze block putih dolomit di kramat jati', '[\"jual jual breeze block putih dolomit di kramat jati\",\"beli jual breeze block putih dolomit di kramat jati\",\"harga jual breeze block putih dolomit di kramat jati per keping\",\"supplier breeze block pabrik plered\",\"screen block minimalis modern\",\"breeze block putih dolomit\"]', 'bofu', 'pemilik_rumah', 'residensial', NULL, NULL, NULL, 'Jual Breeze Block Putih Dolomit Anti Lumut di Kramat Jati, Jakarta Timur — Pabrik Plered (Gratis Ongkir) | Pabrik IndoRoster', 'Pusat jual & beli jual breeze block putih dolomit di kramat jati mutu cetak padat presisi plat baja siku 90°. Pasir abu batu murni & dolomit putih, garansi ama', NULL, NULL, NULL, NULL, '', 'Jual Breeze Block Putih Dolomit Anti Lumut di Kramat Jati, Jakarta Timur — Pabrik Plered (Gratis Ongkir)', 'Mencari pusat penjualan dan tempat pembelian jual breeze block putih dolomit di kramat jati kini hadir lebih dekat, mudah, dan terjamin keasliannya langsung dari sentra pengrajin Plered Purwakarta. Kami menyediakan koleksi lengkap breeze block minimalis modern berstandar presisi matras plat baja siku 90 derajat yang siap dikirim menggunakan armada truk pabrik langsung ke gerbang proyek atau rumah Anda di Jabodetabek, Banten, dan Jawa Barat dengan fasilitas Promo GRATIS ONGKIR dan perlindungan Garansi Bebas Pecah 100% di tempat.', 'Teknik cetak tumbuk padat plat baja siku 90° presisi, menghemat adukan semen perekat tukang hingga 30% dan menghasilkan dinding fasad yang tegak lurus sempurna.', 'Dipercaya oleh ribuan pemilik rumah tinggal, kontraktor tender, dan arsitek di Jabodetabek, Banten, dan Jawa Barat dengan garansi penggantian 100% keping baru di lokasi.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T17:25:26.000000Z', NULL, NULL, '2026-08-31T17:25:27.000000Z', '2026-08-31T17:25:27.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('10142', '1998', 'problem', 'Masalah Breeze Block Rapuh, Bergelombang & Mahalnya Harga Toko Eceran', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Banyak pembeli kecewa setelah membeli loster/breeze block cor basah murahan karena sudutnya yang tidak siku menyebabkan pasangan dinding bergelombang dan boros semen mortar. Selain itu, membeli di toko material perantara sering kali dikenakan biaya tambahan yang mahal tanpa adanya garansi keping retak.</p>', '1', '1', NULL, NULL, '2026-08-31T17:25:27.000000Z', '2026-08-31T17:25:27.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('10143', '1998', 'solution', 'Solusi Pabrik IndoRoster: Presisi Plat Baja Siku 90° & Pasir Abu Batu Murni', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">IndoRoster menghadirkan keping breeze block cetak tumbuk semi-kering padat berbobot 3.8–4.2 kg per keping. Formulasi pasir abu batu murni dan batuan dolomit putih super menjamin pori-pori rapat anti-lumut, bidang siku 90 derajat rapi dengan nat tipis 2–3 mm, serta harga tangan pertama langsung pabrik.</p>', '2', '1', NULL, NULL, '2026-08-31T17:25:27.000000Z', '2026-08-31T17:25:27.000000Z');
