REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('10646', '2166', 'problem', 'Masalah Breeze Block Rapuh, Bergelombang & Mahalnya Harga Toko Eceran', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Banyak pembeli kecewa setelah membeli loster/breeze block cor basah murahan karena sudutnya yang tidak siku menyebabkan pasangan dinding bergelombang dan boros semen mortar. Selain itu, membeli di toko material perantara sering kali dikenakan biaya tambahan yang mahal tanpa adanya garansi keping retak.</p>', '1', '1', NULL, NULL, '2026-08-31T17:25:28.000000Z', '2026-08-31T17:25:28.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('10647', '2166', 'solution', 'Solusi Pabrik IndoRoster: Presisi Plat Baja Siku 90° & Pasir Abu Batu Murni', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">IndoRoster menghadirkan keping breeze block cetak tumbuk semi-kering padat berbobot 3.8–4.2 kg per keping. Formulasi pasir abu batu murni dan batuan dolomit putih super menjamin pori-pori rapat anti-lumut, bidang siku 90 derajat rapi dengan nat tipis 2–3 mm, serta harga tangan pertama langsung pabrik.</p>', '2', '1', NULL, NULL, '2026-08-31T17:25:28.000000Z', '2026-08-31T17:25:28.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('10648', '2166', 'specs', 'Jaminan Logistik & Layanan Kirim Breeze Block', '<div class=\"grid grid-cols-1 md:grid-cols-3 gap-6 not-prose\">
                <div class=\"p-5 rounded-3xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700\">
