REPLACE INTO `seo_pages` (`id`, `slug`, `page_type`, `primary_keyword`, `secondary_keywords`, `search_intent`, `buyer_type`, `project_type`, `use_case`, `seo_location_id`, `location_name`, `title`, `meta_description`, `og_title`, `og_description`, `og_image`, `canonical_url`, `noindex`, `h1`, `opening_text`, `unique_value_proposition`, `unique_evidence`, `unique_angle`, `cta_type`, `cta_text`, `cta_wa_message`, `product_matching_rule`, `product_ids`, `parent_page_id`, `related_page_ids`, `structured_data_type`, `priority_score`, `quality_score`, `quality_details`, `status`, `published_at`, `last_reviewed_at`, `reviewed_by`, `created_at`, `updated_at`) VALUES ('2280', 'jual-concrete-screen-block-kemayoran-jakpus', 'location', 'jual concrete screen block di kemayoran', '[\"jual jual concrete screen block di kemayoran\",\"beli jual concrete screen block di kemayoran\",\"harga jual concrete screen block di kemayoran per keping\",\"supplier breeze block pabrik plered\",\"screen block minimalis modern\",\"breeze block putih dolomit\"]', 'bofu', 'pemilik_rumah', 'residensial', NULL, NULL, NULL, 'Pusat Jual Concrete Screen Block Dinding di Kemayoran, Jakarta Pusat — Pabrik Plered (Gratis Ongkir) | Pabrik IndoRoster', 'Pusat jual & beli jual concrete screen block di kemayoran mutu cetak padat presisi plat baja siku 90°. Pasir abu batu murni & dolomit putih, garansi aman kirim', NULL, NULL, NULL, NULL, '', 'Pusat Jual Concrete Screen Block Dinding di Kemayoran, Jakarta Pusat — Pabrik Plered (Gratis Ongkir)', 'Mencari pusat penjualan dan tempat pembelian jual concrete screen block di kemayoran kini hadir lebih dekat, mudah, dan terjamin keasliannya langsung dari sentra pengrajin Plered Purwakarta. Kami menyediakan koleksi lengkap breeze block minimalis modern berstandar presisi matras plat baja siku 90 derajat yang siap dikirim menggunakan armada truk pabrik langsung ke gerbang proyek atau rumah Anda di Jabodetabek, Banten, dan Jawa Barat dengan fasilitas Promo GRATIS ONGKIR dan perlindungan Garansi Bebas Pecah 100% di tempat.', 'Teknik cetak tumbuk padat plat baja siku 90° presisi, menghemat adukan semen perekat tukang hingga 30% dan menghasilkan dinding fasad yang tegak lurus sempurna.', 'Dipercaya oleh ribuan pemilik rumah tinggal, kontraktor tender, dan arsitek di Jabodetabek, Banten, dan Jawa Barat dengan garansi penggantian 100% keping baru di lokasi.', NULL, 'whatsapp', 'Konsultasi & Minta Penawaran via WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, '0', '99', NULL, 'published', '2026-08-31T17:25:26.000000Z', NULL, NULL, '2026-08-31T17:25:28.000000Z', '2026-08-31T17:25:28.000000Z');
REPLACE INTO `seo_page_sections` (`id`, `seo_page_id`, `section_type`, `heading`, `content`, `sort_order`, `is_visible`, `source`, `unique_angle`, `created_at`, `updated_at`) VALUES ('10988', '2280', 'problem', 'Masalah Breeze Block Rapuh, Bergelombang & Mahalnya Harga Toko Eceran', '<p class=\"text-base text-slate-700 dark:text-slate-300 leading-relaxed mb-4\">Banyak pembeli kecewa setelah membeli loster/breeze block cor basah murahan karena sudutnya yang tidak siku menyebabkan pasangan dinding bergelombang dan boros semen mortar. Selain itu, membeli di toko material perantara sering kali dikenakan biaya tambahan yang mahal tanpa adanya garansi keping retak.</p>', '1', '1', NULL, NULL, '2026-08-31T17:25:28.000000Z', '2026-08-31T17:25:28.000000Z');
